/**
 * The word holds an offset pointer.
 */
#define SUBETHA_NAN_OFFSET_PTR 5

/**
 * The word holds a tag this library does not name. A caller reading one
 * is talking to a newer writer and should leave the value alone rather
 * than guess at it.
 */
#define SUBETHA_NAN_RESERVED 6

/**
 * The widest tag the two-level form accepts. Thirty two would leave no
 * index bits.
 */
#define SUBETHA_NAN_MAX_TAG_BITS 31

/**
 * Lanes in a tile.
 */
#define SUBETHA_TILE_LANES 16

/**
 * The most a lane's payload can carry.
 */
#define SUBETHA_TILE_MAX_PAYLOAD 56

/**
 * Bytes a packed pointer occupies.
 */
#define SUBETHA_UMBRA_BYTES 16

/**
 * Payload bytes a caller may carry beside the tag.
 */
#define SUBETHA_UMBRA_EXT_BYTES 7

/**
 * The tag meaning no caller extension is present.
 */
#define SUBETHA_UMBRA_EXT_NONE 0

/**
 * The target index meaning the pointer aims at nothing.
 */
#define SUBETHA_UMBRA_NIL UINT32_MAX

/**
 * Elements in a list, scanned from the front. Faster for a small set.
 */
#define SUBETHA_UNIVERSAL_VEC 0

/**
 * Elements in a map, probed by hash. Faster for a large one.
 */
#define SUBETHA_UNIVERSAL_MAP 1

/**
 * The index that means "nothing here" at any level of a path.
 */
#define SUBETHA_TOWER_NIL UINT32_MAX

/**
 * In-process memory; the bytes go when the process does.
 */
#define SUBETHA_QOS_VOLATILE 0

/**
 * Named shared memory; outlives the producer while a holder keeps it.
 */
#define SUBETHA_QOS_TRANSIENT 1

/**
 * File-backed; the bytes reach the page cache and can be flushed.
 */
#define SUBETHA_QOS_PERSISTENT 2

/**
 * Loss is acceptable.
 */
#define SUBETHA_QOS_BEST_EFFORT 0

/**
 * Loss is not.
 */
#define SUBETHA_QOS_RELIABLE 1

/**
 * Keep the last `history_depth` items.
 */
#define SUBETHA_QOS_KEEP_LAST 0

/**
 * Keep everything, so `history_depth` says nothing.
 */
#define SUBETHA_QOS_KEEP_ALL 1

/**
 * Each producer's items stay in its own order; producers do not order
 * against each other.
 */
#define SUBETHA_QOS_PER_PRODUCER 0

/**
 * One order across every producer.
 */
#define SUBETHA_QOS_GLOBAL_FIFO 1

/**
 * The streaming preset: volatile, best-effort, last 1024, 100 ms.
 */
#define SUBETHA_QOS_PRESET_STREAMING 0

/**
 * The reliable publish-subscribe preset.
 */
#define SUBETHA_QOS_PRESET_RELIABLE_PUBSUB 1

/**
 * The persistent log preset.
 */
#define SUBETHA_QOS_PRESET_PERSISTENT_LOG 2

/**
 * The id names no binding.
 */
#define SUBETHA_ENDPOINT_NONE 0

/**
 * The id names a ring in this process.
 */
#define SUBETHA_ENDPOINT_LOCAL 1

/**
 * The id names a remote host.
 */
#define SUBETHA_ENDPOINT_REMOTE 2

/**
 * The handle was created by `subetha_deque_create`: it pushes, pops and
 * steals.
 */
#define SUBETHA_DEQUE_OWNER 0

/**
 * The handle was opened by `subetha_deque_open_thief`: it steals.
 */
#define SUBETHA_DEQUE_THIEF 1

/**
 * The insert placed a new entry.
 */
#define SUBETHA_MAP_INSERTED 0

/**
 * The insert overwrote an existing entry's value.
 */
#define SUBETHA_MAP_UPDATED 1

/**
 * The most bytes a key and a value take together in one entry.
 */
#define SUBETHA_HASHMAP_PAYLOAD_BYTES 48

/**
 * The process id in a slot nobody holds.
 */
#define SUBETHA_HEARTBEAT_EMPTY_PID 0

/**
 * Work units one slot's bitmap tracks, so a bit index runs from zero to
 * one below this.
 */
#define SUBETHA_HEARTBEAT_IN_FLIGHT 64

/**
 * The grace window a barrier uses when the caller passes zero: how many
 * epochs a heartbeat slot may be stale before it stops counting as a
 * peer worth waiting for.
 *
 * Spelled as a literal because cbindgen copies the right-hand side into
 * the header verbatim, and a name from another crate does not exist
 * there. `the_default_grace_matches_the_primitive` holds it to the
 * value it mirrors.
 */
#define SUBETHA_BARRIER_GRACE_DEFAULT 3

/**
 * Bytes a lazy value can hold.
 */
#define SUBETHA_LAZY_MAX_BYTES ONCE_PAYLOAD_BYTES

/**
 * Nobody has claimed the value.
 */
#define SUBETHA_LAZY_UNCLAIMED (uint32_t)STATE_EMPTY

/**
 * A caller holds the claim and has not published yet.
 */
#define SUBETHA_LAZY_CLAIMED (uint32_t)STATE_INITIALIZING

/**
 * The value is published.
 */
#define SUBETHA_LAZY_PUBLISHED (uint32_t)STATE_INITIALIZED

/**
 * Remove the backing when the last holder releases.
 */
#define SUBETHA_ARC_UNLINK 0

/**
 * Leave the backing for a process that attaches later.
 */
#define SUBETHA_ARC_KEEP 1

/**
 * The half that ships items to a peer.
 */
#define SUBETHA_SENS_SENDER 0

/**
 * The half that binds and delivers what arrives.
 */
#define SUBETHA_SENS_RECEIVER 1

/**
 * The sliding-window random linear code, for low to moderate loss.
 */
#define SUBETHA_SENS_CODE_RLC 0

/**
 * The block Reed-Solomon code, for high sustained loss.
 */
#define SUBETHA_SENS_CODE_RS 1

/**
 * The accompanying count is a real number.
 */
#define SUBETHA_DROPS_EXACT 0

/**
 * It happened and this host will not say how many. The count is zero and
 * means nothing.
 */
#define SUBETHA_DROPS_OCCURRED 1

/**
 * This host reports nothing either way. The count is zero and means
 * nothing.
 */
#define SUBETHA_DROPS_UNKNOWN 2

/**
 * The half that ships from a local producer ring.
 */
#define SUBETHA_BRIDGE_CLIENT 0

/**
 * The half that binds, accepts one connection and receives.
 */
#define SUBETHA_BRIDGE_SERVER 1

/**
 * One producer to one consumer.
 */
#define SUBETHA_TOPOLOGY_POINT_TO_POINT 0

/**
 * One producer to many consumers.
 */
#define SUBETHA_TOPOLOGY_BROADCAST_TREE 1

/**
 * Peers routing to one another.
 */
#define SUBETHA_TOPOLOGY_ALL_TO_ALL_MESH 2

/**
 * The fan-out at or above which the traffic reads as a broadcast tree.
 */
#define SUBETHA_TOPOLOGY_FAN_OUT_DEFAULT 3

/**
 * The fan-in at or above which the traffic reads as an all-to-all mesh.
 */
#define SUBETHA_TOPOLOGY_FAN_IN_DEFAULT 3

/**
 * The state of a slot nobody holds.
 */
#define SUBETHA_HOLDER_FREE 0

/**
 * The state of a slot claimed whose payload is not decided yet. A
 * caller's payload may not be this value.
 */
#define SUBETHA_HOLDER_RESERVED UINT64_MAX

/**
 * Strategy: the merge by stamp with a consumer-side re-ordering window.
 */
#define SUBETHA_ORDERED_REORDER 0

/**
 * Strategy: the strict merge; the pop is exact, nothing is buffered.
 */
#define SUBETHA_ORDERED_STRICT 1

/**
 * Strategy: direct delivery; the stamps need no correction.
 */
#define SUBETHA_ORDERED_DIRECT 2

/**
 * Bytes one pub/sub slot carries; a publish zero-fills past its payload
 * and a read yields the whole slot.
 */
#define SUBETHA_PUBSUB_PAYLOAD_BYTES 56

/**
 * The index that names no slot; every other index below the capacity
 * names one.
 */
#define SUBETHA_REGION_NIL_INDEX 4294967295

/**
 * The bytes one sampled record takes.
 */
#define SUBETHA_RESERVOIR_ITEM_BYTES 56

/**
 * Bytes one slot holds. A pop buffer must be at least this large.
 */
#define SUBETHA_RING_SLOT_BYTES 64

/**
 * The largest payload every shape accepts. A push between this and
 * `SUBETHA_RING_PLAIN_ITEM_BYTES` succeeds while the ring is in a shape
 * built of single-producer cores (SPSC, MPSC, MPMC), and is refused in the
 * Vyukov shape with `SUBETHA_E_RING_PAYLOAD_TOO_LARGE`.
 */
#define SUBETHA_RING_PAYLOAD_MAX 56

/**
 * The largest plain item a shape built of single-producer cores accepts:
 * every byte of the slot but its last, which holds the item's kind.
 */
#define SUBETHA_RING_PLAIN_ITEM_BYTES 63

/**
 * Ring shape: one producer, one consumer.
 */
#define SUBETHA_RING_SHAPE_SPSC 0

/**
 * Ring shape: several producers, one consumer.
 */
#define SUBETHA_RING_SHAPE_MPSC 1

/**
 * Ring shape: several producers, several consumers.
 */
#define SUBETHA_RING_SHAPE_MPMC 2

/**
 * Ring shape: the Vyukov queue, global FIFO across producers.
 */
#define SUBETHA_RING_SHAPE_VYUKOV 3

/**
 * Shared-memory names resolve per session (`Local\` on Windows).
 */
#define SUBETHA_SHM_SESSION 0

/**
 * Shared-memory names resolve machine-wide (`Global\` on Windows).
 */
#define SUBETHA_SHM_MACHINE 1

/**
 * Shared-memory names resolve in the named-object directory of the
 * AppContainer that `shm_container_sid` names (Windows), reached from
 * outside the container. A process inside the container reaches the same
 * objects with `SUBETHA_SHM_SESSION`. The directory exists only while a
 * process of the container runs. On other platforms the names are the
 * same in every namespace.
 */
#define SUBETHA_SHM_APPCONTAINER 2

/**
 * The shape sidecar's scan cadence when a managed-mode caller names
 * none, in microseconds.
 *
 * The cadence is the added round-trip latency of managed mode, so this
 * is a latency budget rather than a tuned optimum: measured on Linux
 * and FreeBSD from 250 to 10000 microseconds, a request/response round
 * trip costs exactly one interval and a streaming caller costs nothing,
 * with no knee anywhere in that range. A quarter of a millisecond is
 * small against a network hop and against most process-to-process round
 * trips, and costs a few percent of the scanning CPU that a ten-times
 * shorter cadence would.
 */
#define SUBETHA_SCAN_INTERVAL_DEFAULT_US 250

/**
 * Wait without a deadline.
 */
#define SUBETHA_WAIT_FOREVER -1

/**
 * The largest frame that rides inside a slot; a larger one spills to the
 * ring's payload region, which exists from the first spill on.
 */
#define SUBETHA_RING_FRAME_INLINE_BUDGET 51

/**
 * Bytes per block of the payload region the ring creates on its first
 * spilled frame. A frame larger than this is refused with
 * `SUBETHA_E_RING_PAYLOAD_TOO_LARGE`.
 */
#define SUBETHA_RING_FRAME_DEFAULT_BLOCK 8192

/**
 * The frame rode inside the slot.
 */
#define SUBETHA_FRAME_INLINE 0

/**
 * The frame's bytes live in the payload region; the slot carried the offset.
 */
#define SUBETHA_FRAME_OFFSET 1

/**
 * `subetha_ring_recv_any` took a plain item, pushed with
 * `subetha_ring_try_push` or a form of it.
 */
#define SUBETHA_RING_ITEM_PLAIN 0

/**
 * `subetha_ring_recv_any` took a frame that rode inside the slot.
 */
#define SUBETHA_RING_ITEM_FRAME_INLINE 1

/**
 * `subetha_ring_recv_any` took a frame whose bytes lived in the payload
 * region.
 */
#define SUBETHA_RING_ITEM_FRAME_OFFSET 2

/**
 * Inline when the frame fits the budget, else the region.
 */
#define SUBETHA_LAYOUT_AUTO 0

/**
 * Inline only; a frame past the budget is refused.
 */
#define SUBETHA_LAYOUT_FORCE_INLINE 1

/**
 * The region even for a frame that would fit inline.
 */
#define SUBETHA_LAYOUT_FORCE_OFFSET 2

/**
 * No ordering stamps: the ring's payload is the whole slot and its
 * ordering is per-producer FIFO.
 */
#define SUBETHA_STAMPS_NONE 0

/**
 * Stamps from the host's default source: the TSC where it is invariant,
 * the shared counter on x86 without one, the monotonic clock elsewhere.
 * On an open, whatever the creator chose.
 */
#define SUBETHA_STAMPS_DEFAULT 1

/**
 * Stamps from the invariant TSC.
 */
#define SUBETHA_STAMPS_TSC 2

/**
 * Stamps from one shared counter: a total order at the price of one
 * contended increment per push.
 */
#define SUBETHA_STAMPS_SHARED_COUNTER 3

/**
 * Stamps from the system's monotonic clock, in nanoseconds.
 */
#define SUBETHA_STAMPS_MONOTONIC 4

/**
 * Ordering mode: the partition pop, per-producer FIFO; stamps only feed
 * the inversion counter.
 */
#define SUBETHA_ORDERING_UNORDERED 0

/**
 * Ordering mode: a k-way merge by stamp over the ring heads, global FIFO
 * within the stamp source's skew window, under a single drainer.
 */
#define SUBETHA_ORDERING_MERGE_BY_STAMP 1

/**
 * Ordering mode: the merge plus the per-producer watermark gate, exact
 * global FIFO at the cost of waiting on the slowest producer.
 */
#define SUBETHA_ORDERING_MERGE_STRICT 2

/**
 * Contract ordering: no guarantee.
 */
#define SUBETHA_CONTRACT_UNORDERED 0

/**
 * Contract ordering: each producer's items in push order.
 */
#define SUBETHA_CONTRACT_FIFO_PER_PRODUCER 1

/**
 * Contract ordering: one global order across every producer; the
 * per-producer-lane shape is then refused.
 */
#define SUBETHA_CONTRACT_FIFO 2

/**
 * Contract ordering: an item lands at most `k_out_of_order` positions
 * from its global arrival order.
 */
#define SUBETHA_CONTRACT_K_OUT_OF_ORDER 3

/**
 * `last_holder`: the backings outlive the last handle that held them,
 * which is what a ring with no holder table does.
 */
#define SUBETHA_LAST_HOLDER_KEEP 0

/**
 * `last_holder`: the last handle to release removes every backing the
 * ring's prefix names, including the holder table itself.
 */
#define SUBETHA_LAST_HOLDER_UNLINK 1

/**
 * ABI version, major part. The ABI is unstable until the major reaches
 * 1, which it does once tiers 0 through 3 have shipped and a consumer
 * outside this repository has used them. Both halves are load-bearing:
 * the first real user is what finds the awkward signature, and the
 * freeze is what makes an awkward signature permanent.
 */
#define SUBETHA_ABI_VERSION_MAJOR 0

/**
 * ABI version, minor part: the highest tier of `C_ABI_TIERS.md` that
 * has shipped, plus one. A consumer reads it to learn which families it
 * is linked against without probing for symbols, which is the whole
 * reason `subetha_abi_version` exists.
 *
 * | minor | tier | what it adds |
 * |---|---|---|
 * | 1 | 0 | runtime, handle table, error model, the adaptive ring |
 * | 2 | 1 | the remaining rings and channels, stack, deque, notifier |
 * | 3 | 2 | ten shared-state families |
 * | 4 | 3 | eight coordination families |
 * | 5 | 4 | the transports: Sens-O-Matic and the TCP and QUIC bridges |
 * | 6 | 5 | the probabilistic and specialist structures |
 *
 * `abi_version_matches_the_tiers_document` in `tests/header.rs` holds
 * this against the document, so the two cannot drift.
 */
#define SUBETHA_ABI_VERSION_MINOR 6

/**
 * ABI version, patch part. Moves for a fix inside a tier that changes
 * no signature.
 */
#define SUBETHA_ABI_VERSION_PATCH 0

/**
 * Strict mode: no thread starts unless a call says so, data-path calls
 * write into caller buffers, and allocation is documented per function.
 */
#define SUBETHA_MODE_STRICT 0

/**
 * Managed mode: the object runs the background work the Rust API runs.
 */
#define SUBETHA_MODE_MANAGED 1

/**
 * Take the process default chosen at `subetha_init`.
 */
#define SUBETHA_MODE_DEFAULT 2

/**
 * The bytes one version's value takes.
 */
#define SUBETHA_VERSIONED_CHAIN_ITEM_BYTES 48

/**
 * The log2 of the slots one chunk file holds when the caller passes zero.
 *
 * Spelled as a literal because cbindgen copies the right-hand side into
 * the header verbatim, and a name from another crate does not exist
 * there; the assertion below holds it to the value it mirrors.
 */
#define SUBETHA_VERSIONED_INDEX_CHUNK_BITS_DEFAULT 16

/**
 * A key size for identifiers and small integers.
 */
#define SUBETHA_VERSIONED_MAP_KEY_BYTES_SMALL 8

/**
 * The key size `subetha_versioned_map_create_default` uses.
 */
#define SUBETHA_VERSIONED_MAP_KEY_BYTES_DEFAULT 16

/**
 * A key size for compound and textual keys.
 */
#define SUBETHA_VERSIONED_MAP_KEY_BYTES_LARGE 32

/**
 * The value size that pairs with the small key.
 */
#define SUBETHA_VERSIONED_MAP_VALUE_BYTES_SMALL 16

/**
 * The value size `subetha_versioned_map_create_default` uses.
 */
#define SUBETHA_VERSIONED_MAP_VALUE_BYTES_DEFAULT 64

/**
 * The value size that pairs with the large key.
 */
#define SUBETHA_VERSIONED_MAP_VALUE_BYTES_LARGE 256

/**
 * A value size for keys, counters and small records.
 */
#define SUBETHA_VERSIONED_VALUE_BYTES_SMALL 16

/**
 * The value size `subetha_versioned_slab_create_default` uses.
 */
#define SUBETHA_VERSIONED_VALUE_BYTES_DEFAULT 64

/**
 * A value size for records that carry a payload of their own.
 */
#define SUBETHA_VERSIONED_VALUE_BYTES_LARGE 256

/**
 * The depth that pairs with the small value size.
 */
#define SUBETHA_VERSIONED_DEPTH_SMALL 2

/**
 * The depth `subetha_versioned_slab_create_default` uses.
 */
#define SUBETHA_VERSIONED_DEPTH_DEFAULT 4

/**
 * The depth that pairs with the large value size.
 */
#define SUBETHA_VERSIONED_DEPTH_LARGE 8

/**
 * A handle: zero is never issued.
 */
typedef uint64_t subetha_handle;

/**
 * A snapshot of a shared string arena.
 */
typedef struct subetha_arena_stats {
    /**
     * The mode this handle was created in.
     */
    uint32_t mode;
    /**
     * Whether this handle may intern and clear; false for one opened
     * read-only.
     */
    bool writable;
    /**
     * Bytes of room past the header.
     */
    uint64_t capacity_bytes;
    /**
     * Bytes interned so far.
     */
    uint64_t used_bytes;
    /**
     * `capacity_bytes - used_bytes`.
     */
    uint64_t remaining_bytes;
} subetha_arena_stats;

/**
 * What an unlink found.
 */
typedef struct subetha_unlink_report {
    /**
     * Files removed.
     */
    uint64_t removed;
    /**
     * Files the prefix names that were not present.
     */
    uint64_t missing;
    /**
     * Files whose removal the OS refused; the first is named in the detail.
     */
    uint64_t failed;
} subetha_unlink_report;

/**
 * A snapshot of a shared atomic.
 */
typedef struct subetha_atomic_stats {
    /**
     * The mode this handle was created in.
     */
    uint32_t mode;
    /**
     * One of the `SUBETHA_ATOMIC_` constants.
     */
    uint32_t width;
    /**
     * Bytes the value occupies: 4, 8, or 1 for the boolean.
     */
    uint32_t bytes;
} subetha_atomic_stats;

/**
 * A snapshot of a blocking bridge.
 */
typedef struct subetha_blocking_tcp_bridge_stats {
    /**
     * The mode this handle was created in.
     */
    uint32_t mode;
    /**
     * One of `SUBETHA_BRIDGE_CLIENT` or `SUBETHA_BRIDGE_SERVER`.
     */
    uint32_t role;
    /**
     * Items the last finished run carried. A run that ended in an error
     * reports zero, since the primitive counts no partial transfer.
     */
    uint64_t items;
    /**
     * Whether a run is under way right now.
     */
    bool running;
    /**
     * Whether the last run finished.
     */
    bool finished;
    /**
     * The code the last run ended with, or `SUBETHA_OK`.
     */
    int32_t last_code;
} subetha_blocking_tcp_bridge_stats;

/**
 * A snapshot of an adaptive queue handle.
 */
typedef struct subetha_adaptive_queue_stats {
    /**
     * The mode this handle was created in.
     */
    uint32_t mode;
    /**
     * `SUBETHA_ADAPTIVE_SHAPE_RING` or
     * `SUBETHA_ADAPTIVE_SHAPE_WORK_STEALING`, what the queue is now.
     */
    uint32_t shape;
    /**
     * Steps every time the shape changes, so a holder can tell that what
     * it looked at has been superseded.
     */
    uint64_t shape_generation;
    /**
     * `SUBETHA_QOS_PER_PRODUCER` or `SUBETHA_QOS_GLOBAL_FIFO`, whose order
     * a reader gets now.
     */
    uint32_t ordering;
    /**
     * Cross-sender inversions seen so far, which say whether the ordering
     * asked for is being met.
     */
    uint64_t inversions;
    /**
     * Items a send carried on average, this handle's sends counted.
     */
    uint64_t average_batch;
    /**
     * The share of this handle's sends that were batches, from zero to
     * one.
     */
    double batch_share;
    /**
     * Changes of shape the managed scanner made; zero in strict mode.
     */
    uint64_t scanner_changes;
} subetha_adaptive_queue_stats;

/**
 * A FineBloom: 256 bits in four words, bit `i` being bit `i % 64` of
 * `words[i / 64]`. All zero is the empty filter.
 */
typedef struct subetha_fine_bloom {
    /**
     * The filter's bits.
     */
    uint64_t words[4];
} subetha_fine_bloom;

/**
 * A hybrid logical clock: a microsecond reading and a counter that
 * breaks ties within it. Two of them compare lexicographically, the
 * physical part first, which is the order every participant agrees on.
 */
typedef struct subetha_hlc {
    /**
     * Microseconds, from the clock the participants share.
     */
    uint64_t physical_us;
    /**
     * Ticks within one microsecond, so two events in the same
     * microsecond still order.
     */
    uint64_t logical;
} subetha_hlc;

/**
 * One count per participant, which answers whether one event caused
 * another or whether the two happened independently. All zero is the
 * clock before anything has happened.
 */
typedef struct subetha_causal_clock {
    /**
     * Every count, in participant order.
     */
    uint64_t counts[SUBETHA_CAUSAL_CLOCK_NODES];
} subetha_causal_clock;

/**
 * A snapshot of a key-value map.
 */
typedef struct subetha_kv_map_stats {
    /**
     * The mode this handle was created in.
     */
    uint32_t mode;
    /**
     * Slots in the table: the capacity asked for, rounded up to a power of
     * two of at least 2.
     */
    uint64_t capacity;
    /**
     * Keys the map holds.
     */
    uint64_t len;
} subetha_kv_map_stats;

/**
 * What the sidecar has folded from an observed object's observations,
 * field for field the Rust `InstanceStats`.
 */
typedef struct subetha_instance_stats {
    /**
     * Observations drained.
     */
    uint64_t ops_observed;
    /**
     * The latency the observations carried, summed, in raw ticks.
     */
    uint64_t total_latency_ticks;
    /**
     * Observations that reported contention.
     */
    uint64_t contention_ops;
    /**
     * Observations by op kind.
     */
    uint64_t op_kind_counts[SUBETHA_N_OP_KINDS];
    /**
     * Microseconds from registration to the last scan that drained one.
     */
    uint64_t last_drain_us;
    /**
     * Scans whose policy chose another strategy tag.
     */
    uint64_t migrations_triggered;
    /**
     * The distinct producer thread ids seen per op kind, as many of each
     * row as `per_op_kind_distinct_count` says.
     */
    uint32_t per_op_kind_distinct_threads[SUBETHA_N_OP_KINDS][SUBETHA_MAX_TRACKED_THREADS_PER_KIND];
    /**
     * Distinct producer threads per op kind, saturating one past the
     * number tracked.
     */
    uint8_t per_op_kind_distinct_count[SUBETHA_N_OP_KINDS];
} subetha_instance_stats;

/**
 * A policy's decision: given the observed object's statistics and its
 * current tag, answer `SUBETHA_POLICY_STAY`, or `SUBETHA_POLICY_MOVE` with
 * the tag to move to written into `out_tag`, which holds the current tag
 * when the call begins. Any other answer is counted as a policy error and
 * leaves the tag where it is. Called on the sidecar's scan thread; it must
 * not unwind, and it must not unobserve or destroy the handle it decides
 * for, which is refused.
 */
typedef int32_t (*subetha_policy_decide)(void *context,
                                         const struct subetha_instance_stats *stats,
                                         uint32_t current_tag,
                                         uint32_t *out_tag);

/**
 * Called once with the policy's context after its last `decide`, by
 * whichever thread ended the registration; it must not unwind.
 */
typedef void (*subetha_policy_release)(void *context);

/**
 * A snapshot of a reorder window.
 */
typedef struct subetha_reorder_window_stats {
    /**
     * The mode this handle was created in.
     */
    uint32_t mode;
    /**
     * The window right now, which growth changes.
     */
    uint64_t window;
    /**
     * Times an item arrived further out of order than the window covered,
     * each of which widened it.
     */
    uint64_t corrections;
    /**
     * Items held waiting for a gap to fill, which is not how many have
     * passed through.
     */
    uint64_t held;
} subetha_reorder_window_stats;

/**
 * A snapshot of a work queue handle.
 */
typedef struct subetha_work_queue_stats {
    /**
     * The mode this handle was created in.
     */
    uint32_t mode;
    /**
     * `SUBETHA_DEQUE_OWNER` for the handle that made the queue,
     * `SUBETHA_DEQUE_THIEF` for one that attached with
     * `subetha_work_queue_steal_from`.
     */
    uint32_t role;
} subetha_work_queue_stats;

/**
 * A declared contract for a ring: peer ceilings, an ordering envelope,
 * a capacity ceiling. A zero everywhere is the unbounded contract, which
 * is what a ring has when none is declared: registration then grows the
 * ring and never fails.
 */
typedef struct subetha_ring_contract {
    /**
     * Producers that may be registered at once; zero is unbounded.
     */
    uint8_t max_producers;
    /**
     * Consumers that may be registered at once; zero is unbounded.
     */
    uint8_t max_consumers;
    /**
     * One of the `SUBETHA_CONTRACT_` constants.
     */
    uint32_t ordering;
    /**
     * The `k` of `SUBETHA_CONTRACT_K_OUT_OF_ORDER`; ignored otherwise.
     */
    uint32_t k_out_of_order;
    /**
     * A ceiling on the capacity; zero is none.
     */
    uint32_t capacity_bound;
} subetha_ring_contract;

/**
 * Options every ring constructor takes. A C initializer that names the
 * first three fields and leaves the rest zero asks for no stamps, no
 * contract, the lazily created frame region, no security descriptor and
 * no AppContainer.
 */
typedef struct subetha_ring_options {
    /**
     * `SUBETHA_MODE_STRICT`, `SUBETHA_MODE_MANAGED`, or `SUBETHA_MODE_DEFAULT`.
     */
    uint32_t mode;
    /**
     * Waiter slots in each of the ring's two wakers; zero takes the
     * library's default of 32.
     */
    uint32_t max_waiters;
    /**
     * Managed mode only: how often the shape sidecar scans, in
     * microseconds. Zero takes `SUBETHA_SCAN_INTERVAL_DEFAULT_US`.
     * Ignored in strict mode.
     *
     * This value is the added round-trip latency of managed mode: a
     * request and its response each wait for a scan, so a caller doing
     * request/response pays one interval per round trip. Streaming
     * callers pay nothing. Measured on Linux and FreeBSD across 250 to
     * 10000 microseconds, the extra time per round trip equals the
     * interval at every point.
     */
    uint64_t scan_interval_us;
    /**
     * One of the `SUBETHA_STAMPS_` constants. A stamped ring carries an
     * ordering region beside its backings, pays 8 bytes of every slot
     * for the stamp, never takes the Vyukov shape, and refuses frames.
     */
    uint32_t stamps;
    /**
     * The ring's declared contract; all zero declares none.
     */
    struct subetha_ring_contract contract;
    /**
     * Bytes per block of the adaptive ring's frame payload region, which
     * is created at construction when this and `frame_blocks` are both
     * non-zero; a frame up to this size then travels past the slot. Zero
     * leaves the region to be created at
     * `SUBETHA_RING_FRAME_DEFAULT_BLOCK` bytes on the first spilled
     * frame. Set with `frame_blocks` or not at all.
     */
    uint64_t frame_block;
    /**
     * Blocks in the frame payload region; see `frame_block`.
     */
    uint32_t frame_blocks;
    /**
     * Holder slots in the ring's holder table, which is the number of
     * handles that may hold the backings open at once. Zero takes no
     * hold at all, which is the behavior of a ring that names no
     * holder table: the backings outlive every handle. A file-backed or
     * shared-memory ring only; see `last_holder`.
     */
    uint32_t max_holders;
    /**
     * `SUBETHA_LAST_HOLDER_KEEP` or `SUBETHA_LAST_HOLDER_UNLINK`: what
     * becomes of the backings when the last holder releases. Unlinking
     * needs `max_holders`, and the library names no default for it, so
     * asking to unlink with `max_holders` zero is refused rather than
     * given a number nobody chose. A file-backed ring's backings are
     * files and a shared-memory ring's are names; an anonymous ring has
     * neither and refuses a hold.
     */
    uint32_t last_holder;
    /**
     * The security descriptor, as an SDDL string, for every shared-memory
     * region this object creates; null applies the platform's default,
     * which on Windows admits the creating account and administrators.
     * A region that must be mapped from another Windows session needs
     * one. Ignored where the object is not in shared memory and on
     * platforms without descriptors.
     */
    const char *shm_sddl;
    /**
     * With `SUBETHA_SHM_APPCONTAINER`, the container's SID in its string
     * form, `S-1-15-2-...`, which names the directory the object's
     * regions and events are in; the descriptor in `shm_sddl` must then
     * admit that SID. Required with that namespace, and ignored with the
     * others.
     */
    const char *shm_container_sid;
} subetha_ring_options;

