/**
 * Feed `count` round trips under one handle lookup and one claim. Every
 * one is checked before any is fed, so a refusal, naming the first bad
 * one, feeds none.
 *
 * # Safety
 * `microseconds` addresses `count` readable doubles.
 */
int32_t subetha_link_round_trip_shape_observe_many(subetha_handle sensor,
                                                   const double *microseconds,
                                                   size_t count);

/**
 * The round-trip-shape sensor's reading, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_link_round_trip_shape_read(subetha_handle sensor,
                                           struct subetha_link_round_trip_shape_reading *out);

/**
 * Make a sensor looking for a regular beat in the delays and when the
 * next spike is due, with nothing observed yet.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_link_periodicity_create(uint32_t mode, subetha_handle *out);

/**
 * Feed one delay, in microseconds, and when it was taken, in microseconds
 * on a clock that does not step back; a beat can only be found against
 * time.
 */
int32_t subetha_link_periodicity_observe(subetha_handle sensor,
                                         double delay_microseconds,
                                         uint64_t at_microseconds);

/**
 * The periodicity sensor's reading, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_link_periodicity_read(subetha_handle sensor,
                                      struct subetha_link_periodicity_reading *out);

/**
 * Make a sensor estimating the path's capacity from probes of
 * `probe_bytes` bytes each, at least 1, sent in pairs and in trains.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_link_capacity_create(uint32_t probe_bytes, uint32_t mode, subetha_handle *out);

/**
 * Feed the arrival of one probe of a pair, in microseconds on a clock that
 * does not step back: `index` 0 is the pair's first probe and any other
 * value its second. A pair whose two probes arrived together carries no
 * rate and is not counted.
 */
int32_t subetha_link_capacity_observe_pair(subetha_handle sensor,
                                           uint8_t index,
                                           double arrived_microseconds);

/**
 * Feed the arrival of one probe of a train, in microseconds on a clock
 * that does not step back.
 */
int32_t subetha_link_capacity_observe_train(subetha_handle sensor, double arrived_microseconds);

/**
 * Forget every probe and start again, which is what a caller does when
 * the path may have changed.
 */
int32_t subetha_link_capacity_reset(subetha_handle sensor);

/**
 * The capacity sensor's reading, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_link_capacity_read(subetha_handle sensor,
                                   struct subetha_link_capacity_reading *out);

/**
 * Make a sensor forecasting what the next interval's traffic is likely to
 * be from what the last ones were, with nothing observed yet.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_link_forecast_create(uint32_t mode, subetha_handle *out);

/**
 * Feed one interval: `bytes` arrived over `seconds`, which must be finite
 * and above zero.
 */
int32_t subetha_link_forecast_observe(subetha_handle sensor, uint64_t bytes, double seconds);

/**
 * The forecast sensor's reading, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_link_forecast_read(subetha_handle sensor,
                                   struct subetha_link_forecast_reading *out);

/**
 * Make a sensor watching for the route changing under the traffic, with
 * nothing observed yet.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_link_path_changes_create(uint32_t mode, subetha_handle *out);

/**
 * Feed one item received: its remaining time to live, its two-bit
 * congestion marking (3 is congestion experienced), and how many hops it
 * took.
 */
int32_t subetha_link_path_changes_observe(subetha_handle sensor,
                                          uint8_t ttl,
                                          uint8_t congestion_mark,
                                          uint8_t hops);

/**
 * The path-changes sensor's reading, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_link_path_changes_read(subetha_handle sensor,
                                       struct subetha_link_path_changes_reading *out);

/**
 * Obtain the laned map under `dir`: `lanes` trees of `nodes_per_lane`
 * nodes each for `key_size`-byte keys and `value_size`-byte values, one
 * epoch table they share holding `max_pins` pins, and the claims table
 * beside them.
 *
 * # Safety
 * `dir` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_laned_map_create(const char *dir,
                                 uint32_t lanes,
                                 uint64_t nodes_per_lane,
                                 size_t key_size,
                                 size_t value_size,
                                 uint64_t max_pins,
                                 uint32_t mode,
                                 subetha_handle *out);

/**
 * Attach to the laned map another process created under `dir`; its files
 * must exist. `SUBETHA_E_IO` names an absent one.
 *
 * # Safety
 * `dir` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_laned_map_open(const char *dir,
                               uint32_t lanes,
                               uint64_t nodes_per_lane,
                               size_t key_size,
                               size_t value_size,
                               uint64_t max_pins,
                               uint32_t mode,
                               subetha_handle *out);

/**
 * Claim any free lane, for a statement inserting keys that do not yet
 * exist, and report which into `out_lane`. `SUBETHA_E_WOULD_BLOCK` when
 * every lane is held.
 *
 * # Safety
 * `out_lane` is a valid pointer.
 */
int32_t subetha_laned_map_claim_lane(subetha_handle handle, uint32_t *out_lane);

/**
 * Claim the lane that owns `key`, for a statement that must remove or
 * rewrite a key that already exists, and report which into `out_lane`.
 * `SUBETHA_E_MAP_KEY_ABSENT` when no lane holds it and
 * `SUBETHA_E_WOULD_BLOCK` when its lane is held by another statement,
 * which the caller retries rather than writing elsewhere, because
 * elsewhere is a different tree.
 *
 * # Safety
 * `key` points to `key_len` readable bytes; `out_lane` is a valid pointer.
 */
int32_t subetha_laned_map_claim_lane_for(subetha_handle handle,
                                         const uint8_t *key,
                                         size_t key_len,
                                         uint32_t *out_lane);

/**
 * Release a lane this process claimed, so another statement may take it.
 */
int32_t subetha_laned_map_release_lane(subetha_handle handle, uint32_t lane);

/**
 * Release the lanes of holders whose process is gone, reporting how many
 * came back through `out_reaped` when that is not null.
 *
 * # Safety
 * `out_reaped` is null or a valid pointer.
 */
int32_t subetha_laned_map_reap_dead_claims(subetha_handle handle, uint64_t *out_reaped);

/**
 * Make `value` current at `key` in `lane`, at a fresh epoch. The caller
 * holds `lane`.
 *
 * # Safety
 * `key` points to `key_len` readable bytes and `value` to `value_len`.
 */
int32_t subetha_laned_map_insert(subetha_handle handle,
                                 uint32_t lane,
                                 const uint8_t *key,
                                 size_t key_len,
                                 const uint8_t *value,
                                 size_t value_len);

/**
 * Stamp `key` superseded in `lane` at a fresh epoch, writing what was
 * current into `out`. `SUBETHA_E_WRONG_KIND` names the lane that holds
 * the key when this one does not.
 *
 * # Safety
 * `key` points to `key_len` readable bytes; `out` points to `cap`
 * writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_laned_map_remove(subetha_handle handle,
                                 uint32_t lane,
                                 const uint8_t *key,
                                 size_t key_len,
                                 uint8_t *out,
                                 size_t cap,
                                 size_t *out_len);

/**
 * The value current at `key` into `out`, from whichever lane holds it.
 * `SUBETHA_E_MAP_KEY_ABSENT` when no lane does.
 *
 * # Safety
 * `key` points to `key_len` readable bytes; `out` points to `cap`
 * writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_laned_map_get(subetha_handle handle,
                              const uint8_t *key,
                              size_t key_len,
                              uint8_t *out,
                              size_t cap,
                              size_t *out_len);

/**
 * The lane holding `key` into `out_lane`.
 * `SUBETHA_E_MAP_KEY_ABSENT` when no lane does.
 *
 * # Safety
 * `key` points to `key_len` readable bytes; `out_lane` is a valid pointer.
 */
int32_t subetha_laned_map_lane_of(subetha_handle handle,
                                  const uint8_t *key,
                                  size_t key_len,
                                  uint32_t *out_lane);

/**
 * One page of the entries current at one moment, merged across every
 * lane in key order, packed into `out` as key bytes then value bytes per
 * entry.
 *
 * `after` is null to start, or the frontier of the previous page to
 * resume strictly past it. `out_frontier` receives the frontier this page
 * reached and `out_has_frontier` whether there is one: no frontier means
 * every lane reached the end and the walk is done. Rows beyond the
 * frontier are withheld even where a lane already walked them, because a
 * lane that stopped earlier may still hold a smaller key.
 *
 * # Safety
 * `after` and `out_frontier` are null or point to `key_size` bytes;
 * `out` points to `cap` writable bytes; the out pointers are valid.
 */
int32_t subetha_laned_map_range(subetha_handle handle,
                                const uint8_t *after,
                                size_t limit,
                                uint8_t *out,
                                size_t cap,
                                size_t *out_len,
                                size_t *out_count,
                                uint8_t *out_frontier,
                                bool *out_has_frontier);

/**
 * Drop every tombstone no pin can reach, in every lane, reporting how
 * many went through `out_freed` when that is not null.
 *
 * # Safety
 * `out_freed` is null or a valid pointer.
 */
int32_t subetha_laned_map_sweep(subetha_handle handle, uint64_t *out_freed);

/**
 * Undo every stamp at `epoch` in every lane, for an epoch whose holder
 * died part way through a compound write. Reports the entries touched
 * through `out_touched` when that is not null.
 *
 * # Safety
 * `out_touched` is null or a valid pointer.
 */
int32_t subetha_laned_map_void_epoch(subetha_handle handle, uint64_t epoch, uint64_t *out_touched);

/**
 * Push every lane's dirty pages to disk, returning when they are durable.
 */
int32_t subetha_laned_map_flush(subetha_handle handle);

/**
 * A snapshot of the map into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_laned_map_read_stats(subetha_handle handle, struct subetha_laned_map_stats *out);

/**
 * Obtain the election at `path`: an empty one is initialized when the
 * file does not exist, an existing one is attached with its leader and
 * term in place.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_leader_create(const char *path, uint32_t mode, subetha_handle *out);

/**
 * Attach to the election another process created at `path`; the file
 * must exist. `SUBETHA_E_IO` names an absent file.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_leader_open(const char *path, uint32_t mode, subetha_handle *out);

/**
 * Truncate the file at `path` and lay out an election with no leader,
 * discarding whatever a live one holds.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_leader_reset(const char *path, uint32_t mode, subetha_handle *out);

/**
 * Try to take leadership for `pid`, and write whether it was taken into
 * `out_claimed`. It is taken when nobody leads, when `pid` is below the
 * current leader's and so preempts it, or when the leader's heartbeat
 * has fallen more than `grace_epochs` behind the global epoch.
 *
 * # Safety
 * `out_claimed` is a valid pointer.
 */
int32_t subetha_leader_try_claim(subetha_handle handle,
                                 uint32_t pid,
                                 uint64_t grace_epochs,
                                 bool *out_claimed);

/**
 * Refresh the leader's heartbeat, and write whether `pid` still leads
 * into `out_still_leader`. A leader calls this faster than the epoch is
 * ticked, or the grace window expires under it.
 *
 * # Safety
 * `out_still_leader` is null or a valid pointer.
 */
int32_t subetha_leader_beat(subetha_handle handle, uint32_t pid, bool *out_still_leader);

/**
 * Give up leadership, and write whether `pid` was leading into
 * `out_stepped`. A process shutting down cleanly does this so the next
 * leader takes over at once rather than waiting out the grace window.
 *
 * # Safety
 * `out_stepped` is null or a valid pointer.
 */
int32_t subetha_leader_step_down(subetha_handle handle, uint32_t pid, bool *out_stepped);

/**
 * Advance the global epoch and write it into `out_epoch`. The grace
 * window is measured against this, so a departed leader is only noticed
 * once something ticks it.
 *
 * # Safety
 * `out_epoch` is null or a valid pointer.
 */
int32_t subetha_leader_tick_epoch(subetha_handle handle, uint64_t *out_epoch);

/**
 * A snapshot of the election into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_leader_read_stats(subetha_handle handle, struct subetha_leader_stats *out);

/**
 * Write the election's page to its file.
 */
int32_t subetha_leader_flush(subetha_handle handle);

/**
 * Remove the election's file at `path`. The contract is
 * `subetha_ring_unlink`'s.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `report` is null or a valid
 * pointer.
 */
int32_t subetha_leader_unlink(const char *path, struct subetha_unlink_report *report);

/**
 * This process's id, which is what a leadership claim and a heartbeat
 * slot are made by. A C caller can reach its own platform's call for
 * this; it is here so a program using the ABI needs nothing else.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_current_pid(uint32_t *out);

/**
 * Obtain the list at `path` holding up to `capacity` nodes, the sentinel
 * head among them, at `layout`: an empty one is initialized when the file
 * does not exist, an existing one is attached with its nodes in place. A
 * file built with another capacity or layout is a
 * `SUBETHA_E_LAYOUT_MISMATCH`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `layout` and `out` are valid
 * pointers.
 */
int32_t subetha_list_create(const char *path,
                            uint32_t capacity,
                            const struct subetha_element_layout *layout,
                            uint32_t mode,
                            subetha_handle *out);

/**
 * Attach to the list another process created at `path`; the file must
 * exist and already hold the sentinel head. `SUBETHA_E_IO` names an
 * absent file.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `layout` and `out` are valid
 * pointers.
 */
int32_t subetha_list_open(const char *path,
                          uint32_t capacity,
                          const struct subetha_element_layout *layout,
                          uint32_t mode,
                          subetha_handle *out);

/**
 * Truncate the file at `path` and initialize an empty list there,
 * invalidating every index other handles hold. On Windows the file must
 * not be mapped by any handle.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `layout` and `out` are valid
 * pointers.
 */
int32_t subetha_list_reset(const char *path,
                           uint32_t capacity,
                           const struct subetha_element_layout *layout,
                           uint32_t mode,
                           subetha_handle *out);

/**
 * Add `data`, exactly `element_size` bytes, at the front and write the
 * new node's handle into `out_index`. `SUBETHA_E_RING_FULL` when every
 * slot is taken.
 *
 * # Safety
 * `data` points to `len` readable bytes; `out_index` is a valid pointer.
 */
int32_t subetha_list_push_front(subetha_handle handle,
                                const uint8_t *data,
                                size_t len,
                                uint64_t *out_index);

/**
 * Add `data`, exactly `element_size` bytes, at the back and write the new
 * node's handle into `out_index`.
 *
 * # Safety
 * `data` points to `len` readable bytes; `out_index` is a valid pointer.
 */
int32_t subetha_list_push_back(subetha_handle handle,
                               const uint8_t *data,
                               size_t len,
                               uint64_t *out_index);

/**
 * Remove the first node, its value into `out`, at least `element_size`
 * bytes, and its length into `out_len`. `SUBETHA_E_RING_EMPTY` when the
 * list holds no node.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_list_pop_front(subetha_handle handle, uint8_t *out, size_t cap, size_t *out_len);

/**
 * Remove the last node, its value into `out`, at least `element_size`
 * bytes.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_list_pop_back(subetha_handle handle, uint8_t *out, size_t cap, size_t *out_len);

/**
 * Remove the node `index` names, wherever it sits, its value into `out`,
 * at least `element_size` bytes. `SUBETHA_E_OUT_OF_BOUNDS` for the
 * sentinel head, the nil handle, a slot past the capacity, or a handle
 * whose node is gone.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_list_remove(subetha_handle handle,
                            uint64_t index,
                            uint8_t *out,
                            size_t cap,
                            size_t *out_len);

/**
 * Copy the value of the node `index` names into `out`, at least
 * `element_size` bytes.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_list_get(subetha_handle handle,
                         uint64_t index,
                         uint8_t *out,
                         size_t cap,
                         size_t *out_len);

/**
 * Overwrite the value of the node `index` names with `data`, exactly
 * `element_size` bytes, leaving the node where it is.
 *
 * # Safety
 * `data` points to `len` readable bytes.
 */
int32_t subetha_list_set(subetha_handle handle, uint64_t index, const uint8_t *data, size_t len);

/**
 * The first node's handle into `out`, or `SUBETHA_LIST_HEAD_INDEX` when
 * the list holds no node.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_list_first(subetha_handle handle, uint64_t *out);

/**
 * The last node's handle into `out`, or `SUBETHA_LIST_HEAD_INDEX` when
 * the list holds no node.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_list_last(subetha_handle handle, uint64_t *out);

/**
 * The handle after `index` into `out`, which is
 * `SUBETHA_LIST_HEAD_INDEX` once the walk has passed the last node.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_list_next(subetha_handle handle, uint64_t index, uint64_t *out);

/**
 * The handle before `index` into `out`, which is
 * `SUBETHA_LIST_HEAD_INDEX` once the walk has passed the first node.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_list_prev(subetha_handle handle, uint64_t index, uint64_t *out);

/**
 * A snapshot of the list into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_list_read_stats(subetha_handle handle, struct subetha_list_stats *out);

/**
 * Free what processes killed mid-operation left in the list now: each node
 * one took and never linked or swapped out and never freed, and each value
 * frame one took for a set. How many came back goes into `out_freed`.
 * Attaching does the same, as does the next push into a full list once the
 * operating system reports that a process attached to the list exited.
 *
 * # Safety
 * `out_freed` is a valid pointer.
 */
int32_t subetha_list_reclaim(subetha_handle handle, uint64_t *out_freed);

/**
 * Write the list's dirty pages to its file.
 */
int32_t subetha_list_flush(subetha_handle handle);

/**
 * Remove the list file at `path`. The contract is `subetha_ring_unlink`'s.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `report` is null or a valid
 * pointer.
 */
int32_t subetha_list_unlink(const char *path, struct subetha_unlink_report *report);

/**
 * Create a locale-adaptive ring under `base_path`, or attach to one that
 * exists there. The ring starts in anonymous memory. Stamps come from the
 * host's default source or not at all, and the ring declares no
 * contract.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `options` and `out` are
 * valid pointers.
 */
int32_t subetha_locale_ring_create(const char *base_path,
                                   uint32_t max_producers,
                                   uint32_t max_consumers,
                                   uint32_t capacity,
                                   const struct subetha_ring_options *options,
                                   subetha_handle *out);

/**
 * Attach to the locale ring another process created under `base_path`
 * with the same counts and capacity, without re-initializing any
 * backing; the locale tag, the generation and the file and shared-memory
 * backings are the creator's, and this handle's anonymous backing is its
 * own. `stamps` in the options must match the creator's choice.
 * `SUBETHA_E_RING_IO` names an absent backing and
 * `SUBETHA_E_RING_LAYOUT_MISMATCH` one of another shape.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `options` and `out` are
 * valid pointers.
 */
int32_t subetha_locale_ring_open(const char *base_path,
                                 uint32_t max_producers,
                                 uint32_t max_consumers,
                                 uint32_t capacity,
                                 const struct subetha_ring_options *options,
                                 subetha_handle *out);

/**
 * Register as a producer on all three backings, so the live one always
 * has the registration.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_locale_ring_register_producer(subetha_handle handle, uint32_t *out);

/**
 * Register as a consumer on all three backings.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_locale_ring_register_consumer(subetha_handle handle, uint32_t *out);

/**
 * Give back a producer id `subetha_locale_ring_register_producer` wrote,
 * on all three backings. The id is handed out again; the items the
 * producer sent stay until a consumer receives them. An id no ring can
 * issue is `SUBETHA_E_INVALID_ARGUMENT`.
 */
int32_t subetha_locale_ring_unregister_producer(subetha_handle handle, uint32_t producer_id);

/**
 * Give back a consumer id `subetha_locale_ring_register_consumer` wrote,
 * on all three backings. The rings the consumer owned pass to the
 * consumers that remain, so their items go on being received. An id no
 * ring can issue is `SUBETHA_E_INVALID_ARGUMENT`.
 */
int32_t subetha_locale_ring_unregister_consumer(subetha_handle handle, uint32_t consumer_id);

/**
 * Push into the live locale without waiting; the slot semantics are
 * `subetha_ring_try_push`'s.
 *
 * # Safety
 * `data` points to `len` readable bytes.
 */
int32_t subetha_locale_ring_try_push(subetha_handle handle,
                                     uint32_t producer_id,
                                     const uint8_t *data,
                                     size_t len);

/**
 * Pop from the live locale without waiting; the slot semantics are
 * `subetha_ring_try_pop`'s.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_locale_ring_try_pop(subetha_handle handle,
                                    uint32_t consumer_id,
                                    uint8_t *out,
                                    size_t cap,
                                    size_t *out_len);

/**
 * Push, parking until there is room or `timeout_ms` elapses; the waiting
 * contract is `subetha_ring_push_wait`'s.
 *
 * # Safety
 * `data` points to `len` readable bytes.
 */
int32_t subetha_locale_ring_push_wait(subetha_handle handle,
                                      uint32_t producer_id,
                                      const uint8_t *data,
                                      size_t len,
                                      int64_t timeout_ms);

/**
 * Pop, parking until an item arrives or `timeout_ms` elapses; the waiting
 * contract is `subetha_ring_pop_wait`'s.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_locale_ring_pop_wait(subetha_handle handle,
                                     uint32_t consumer_id,
                                     uint8_t *out,
                                     size_t cap,
                                     size_t *out_len,
                                     int64_t timeout_ms);

/**
 * Move the ring to `locale`, one of the `SUBETHA_LOCALE_` constants,
 * carrying the items in flight across. A migration to the live locale
 * is a no-op. In managed mode the locale is also what the sidecar is
 * asked for, as `subetha_locale_ring_request` asks, so the sidecar keeps
 * the ring there. Every thread parked in a wait on the ring, in any
 * process, wakes and looks again, since each handle's anonymous backing
 * is its own and a move into or out of it changes what a waiter finds.
 */
int32_t subetha_locale_ring_migrate(subetha_handle handle, uint32_t locale);

/**
 * Managed mode: tell the sidecar the locale the caller wants; it migrates
 * once its hysteresis has elapsed, waking every waiter as
 * `subetha_locale_ring_migrate` does. `SUBETHA_E_NOT_SUPPORTED` in strict
 * mode, where `subetha_locale_ring_migrate` is the call.
 */
int32_t subetha_locale_ring_request(subetha_handle handle, uint32_t locale);

/**
 * Set the ordering mode of a stamped locale ring on all three backings;
 * the contract is `subetha_ring_set_ordering_mode`'s.
 */
int32_t subetha_locale_ring_set_ordering_mode(subetha_handle handle, uint32_t mode);

/**
 * A snapshot of the ring's state into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_locale_ring_read_stats(subetha_handle handle, struct subetha_locale_stats *out);

/**
 * Wake every thread parked in a wait on this ring; each re-checks the
 * ring and parks again unless it finds what it waited for.
 */
int32_t subetha_locale_ring_wake_all(subetha_handle handle);

/**
 * Remove what a locale ring under `base_path` leaves behind. The ring
 * removes its tag, its generation and its file backing when its handle is
 * destroyed, in every process that holds one, so a process that keeps
 * its handle keeps its mapping while the files are already gone; this
 * call removes the two wakers and any file a peer's destroy could not,
 * for the creation hint `max_producers`. The contract is
 * `subetha_ring_unlink`'s.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `report` is null or a
 * valid pointer.
 */
int32_t subetha_locale_ring_unlink(const char *base_path,
                                   uint32_t max_producers,
                                   struct subetha_unlink_report *report);

/**
 * Create a blocking MPMC grid in anonymous memory: `n_producers` rings of
 * `capacity` slots partitioned across `n_consumers` consumers, one handle
 * each into `out_producers` and `out_consumers`.
 *
 * # Safety
 * `out_producers` points to `n_producers` writable handles and
 * `out_consumers` to `n_consumers`.
 */
int32_t subetha_mpmc_create_anon_grid(uint32_t n_producers,
                                      uint32_t n_consumers,
                                      uint32_t capacity,
                                      uint32_t mode,
                                      subetha_handle *out_producers,
                                      subetha_handle *out_consumers);

/**
 * Create a file-backed blocking MPMC grid under `path_prefix`.
 *
 * # Safety
 * `path_prefix` is a NUL-terminated UTF-8 string; `out_producers` points to
 * `n_producers` writable handles and `out_consumers` to `n_consumers`.
 */
int32_t subetha_mpmc_create_grid(const char *path_prefix,
                                 uint32_t n_producers,
                                 uint32_t n_consumers,
                                 uint32_t capacity,
                                 uint32_t mode,
                                 subetha_handle *out_producers,
                                 subetha_handle *out_consumers);

/**
 * Attach to a file-backed blocking MPMC grid another process created
 * under `path_prefix`, with the counts and capacity it was created with.
 *
 * # Safety
 * `path_prefix` is a NUL-terminated UTF-8 string; `out_producers` points to
 * `n_producers` writable handles and `out_consumers` to `n_consumers`.
 */
int32_t subetha_mpmc_open_grid(const char *path_prefix,
                               uint32_t n_producers,
                               uint32_t n_consumers,
                               uint32_t expected_capacity,
                               uint32_t mode,
                               subetha_handle *out_producers,
                               subetha_handle *out_consumers);

/**
 * Push `len` bytes into this producer's ring without waiting; the slot
 * semantics are the adaptive ring's. `SUBETHA_E_RING_FULL` when there is
 * no room.
 *
 * # Safety
 * `data` points to `len` readable bytes.
 */
int32_t subetha_mpmc_try_push(subetha_handle handle, const uint8_t *data, size_t len);

/**
 * Push, parking until this producer's ring has room or `timeout_ms`
 * elapses; the waiting contract is `subetha_ring_push_wait`'s.
 *
 * # Safety
 * `data` points to `len` readable bytes.
 */
int32_t subetha_mpmc_push_wait(subetha_handle handle,
                               const uint8_t *data,
                               size_t len,
                               int64_t timeout_ms);

/**
 * Push `count` payloads of `len` bytes each into this producer's ring,
 * the first at `items` and each next one `stride` bytes on, under one
 * handle lookup and one panic guard. The batch contract is
 * `subetha_ring_try_push_many`'s.
 *
 * # Safety
 * `items` addresses `count * stride` readable bytes; `out_done` is a
 * valid pointer.
 */
int32_t subetha_mpmc_try_push_many(subetha_handle handle,
                                   const uint8_t *items,
                                   size_t stride,
                                   size_t len,
                                   size_t count,
                                   size_t *out_done);

/**
 * Pop up to `count` slots from the grid, the first written at `out` and
 * each next one `stride` bytes on. The batch contract is
 * `subetha_ring_try_pop_many`'s.
 *
 * # Safety
 * `out` addresses `count * stride` writable bytes; `out_done` is a valid
 * pointer.
 */
int32_t subetha_mpmc_try_pop_many(subetha_handle handle,
                                  uint8_t *out,
                                  size_t stride,
                                  size_t count,
                                  size_t *out_done);

/**
 * Pop one slot from whichever ring of this consumer's subset has one,
 * without waiting; `cap` must be at least `SUBETHA_RING_SLOT_BYTES`.
 * `SUBETHA_E_RING_EMPTY` when the subset is empty.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_mpmc_try_pop(subetha_handle handle, uint8_t *out, size_t cap, size_t *out_len);

/**
 * Pop, parking until a producer of this consumer's subset pushes or
 * `timeout_ms` elapses; the waiting contract is `subetha_ring_pop_wait`'s.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_mpmc_pop_wait(subetha_handle handle,
                              uint8_t *out,
                              size_t cap,
                              size_t *out_len,
                              int64_t timeout_ms);

/**
 * A snapshot of one producer into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_mpmc_producer_read_stats(subetha_handle handle,
                                         struct subetha_mpmc_producer_stats *out);

/**
 * A snapshot of one consumer into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_mpmc_consumer_read_stats(subetha_handle handle,
                                         struct subetha_mpmc_consumer_stats *out);

/**
 * Remove every file a file-backed blocking MPMC grid under `path_prefix`
 * names, for the counts it was created with. The contract is
 * `subetha_ring_unlink`'s.
 *
 * # Safety
 * `path_prefix` is a NUL-terminated UTF-8 string; `report` is null or a
 * valid pointer.
 */
int32_t subetha_mpmc_unlink(const char *path_prefix,
                            uint32_t n_producers,
                            uint32_t n_consumers,
                            struct subetha_unlink_report *report);

/**
 * Create the bit vector at `path`, or attach to one already there with
 * the same capacity. Every bit starts clear.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_bit_vec_create(const char *path,
                               uint64_t capacity_bits,
                               uint32_t mode,
                               subetha_handle *out);

/**
 * Truncate the file at `path` and initialize an all-clear vector,
 * discarding the bits live peers share. For a caller that knows it owns
 * the path.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_bit_vec_reset(const char *path,
                              uint64_t capacity_bits,
                              uint32_t mode,
                              subetha_handle *out);

/**
 * Attach to a vector another process created at `path`. The file must
 * exist and must be at least as large as `capacity_bits` needs, or the
 * answer is `SUBETHA_E_LAYOUT_MISMATCH`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_bit_vec_open(const char *path,
                             uint64_t capacity_bits,
                             uint32_t mode,
                             subetha_handle *out);

/**
 * Set bit `index`, writing whether it had already been set into `was`.
 *
 * The previous value is what makes this usable as a claim: two processes
 * setting the same bit both succeed, and exactly one is told it was the
 * one that changed it. `was` may be null when that is not wanted.
 *
 * This and `subetha_bit_vec_clear` report the value from before the
 * call. `subetha_bit_vec_toggle` reports the value after it.
 *
 * # Safety
 * `was` is null or a valid pointer.
 */
int32_t subetha_bit_vec_set(subetha_handle handle, uint64_t index, bool *was);

/**
 * Clear bit `index`, writing whether it had been set into `was`.
 *
 * # Safety
 * `was` is null or a valid pointer.
 */
int32_t subetha_bit_vec_clear(subetha_handle handle, uint64_t index, bool *was);

/**
 * Flip bit `index`, writing the value it now holds into `now`.
 *
 * The parameter is `now` and not `was` because this one differs from its
 * two siblings: `subetha_bit_vec_set` and `subetha_bit_vec_clear` report
 * the value from before the call, and this reports the value after it.
 * A caller using all three must not read them alike.
 *
 * # Safety
 * `now` is null or a valid pointer.
 */
int32_t subetha_bit_vec_toggle(subetha_handle handle, uint64_t index, bool *now);

/**
 * Read bit `index` into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_bit_vec_get(subetha_handle handle, uint64_t index, bool *out);

/**
 * Set every bit from `lo` up to but not including `hi`.
 *
 * The range is not one atomic step: a reader during it sees some of the
 * bits changed and some not. Only the individual bits are atomic.
 */
int32_t subetha_bit_vec_set_range(subetha_handle handle, uint64_t lo, uint64_t hi);

/**
 * Clear every bit from `lo` up to but not including `hi`, with the same
 * caution about the range not being one step.
 */
int32_t subetha_bit_vec_clear_range(subetha_handle handle, uint64_t lo, uint64_t hi);

/**
 * Set every bit in the vector.
 */
int32_t subetha_bit_vec_set_all(subetha_handle handle);

/**
 * Clear every bit in the vector.
 */
int32_t subetha_bit_vec_clear_all(subetha_handle handle);

/**
 * Push the mapped bytes to disk and wait for them.
 */
int32_t subetha_bit_vec_flush(subetha_handle handle);

/**
 * Ask for the mapped bytes to reach disk without waiting.
 */
int32_t subetha_bit_vec_flush_async(subetha_handle handle);

/**
 * A snapshot of this vector into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_bit_vec_read_stats(subetha_handle handle, struct subetha_bit_vec_stats *out);

/**
 * Create the sketch at `path`, or attach to one already there with the
 * same precision.
 *
 * Precision decides both the accuracy and the size: the file holds two
 * to the `precision` registers, so raising it costs memory and lowers
 * the error.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_hll_create(const char *path,
                           uint32_t precision,
                           uint32_t mode,
                           subetha_handle *out);

/**
 * Attach to a sketch another process created at `path`. The file must
 * exist and match `precision`, or the answer is
 * `SUBETHA_E_LAYOUT_MISMATCH`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_hll_open(const char *path, uint32_t precision, uint32_t mode, subetha_handle *out);

/**
 * Record that `item` was seen.
 *
 * Inserting the same item again changes nothing, which is what makes the
 * estimate a distinct count rather than a total. There is no answer to
 * return: the sketch cannot tell a caller whether this item was new.
 *
 * # Safety
 * `item` points to `len` readable bytes.
 */
int32_t subetha_hll_insert(subetha_handle handle, const uint8_t *item, size_t len);

/**
 * The number of distinct items the registers imply, into `out`.
 *
 * An estimate. A sketch that has seen nothing answers zero, and one that
 * has seen a great many answers a number near but rarely equal to the
 * truth. Another process inserting during this read moves it.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_hll_estimate(subetha_handle handle, uint64_t *out);

/**
 * Return every register to zero, so the sketch reads as having seen
 * nothing.
 *
 * This is visible to every process sharing the file, not only to this
 * handle: a peer mid-insert keeps whatever it writes next, and the
 * counts before the reset are gone for all of them.
 */
int32_t subetha_hll_reset(subetha_handle handle);

/**
 * Push the mapped bytes to disk and wait for them.
 */
int32_t subetha_hll_flush(subetha_handle handle);

/**
 * Ask for the mapped bytes to reach disk without waiting.
 */
int32_t subetha_hll_flush_async(subetha_handle handle);

/**
 * A snapshot of this sketch into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_hll_read_stats(subetha_handle handle, struct subetha_hll_stats *out);

/**
 * Create a graph under `base_path`, holding up to `max_nodes` nodes and
 * `max_edges` edges whose values are the given sizes.
 *
 * Two files are made beside that prefix: the nodes and the edges.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_graph_create(const char *base_path,
                             uint64_t max_nodes,
                             uint64_t max_edges,
                             uint64_t node_value_size,
                             uint64_t edge_value_size,
                             uint32_t mode,
                             subetha_handle *out);

/**
 * Attach to a graph another process created under `base_path`, with the
 * same shape.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_graph_open(const char *base_path,
                           uint64_t max_nodes,
                           uint64_t max_edges,
                           uint64_t node_value_size,
                           uint64_t edge_value_size,
                           uint32_t mode,
                           subetha_handle *out);

/**
 * Add a node carrying `value`, writing the index it took into `node_out`.
 *
 * # Safety
 * `value` points to at least `value_len` bytes; `node_out` is valid.
 */
int32_t subetha_graph_add_node(subetha_handle handle,
                               const uint8_t *value,
                               uint64_t value_len,
                               uint32_t *node_out);

/**
 * Add an edge from `src` to `dst` carrying `value`, writing the index it
 * took into `edge_out`. Both nodes must be live.
 *
 * The edge goes at the front of the source's chain, so a walk sees the
 * reverse of the order edges were added. No order is promised.
 *
 * # Safety
 * `value` points to at least `value_len` bytes; `edge_out` is valid.
 */
int32_t subetha_graph_add_edge(subetha_handle handle,
                               uint32_t src,
                               uint32_t dst,
                               const uint8_t *value,
                               uint64_t value_len,
                               uint32_t *edge_out);

/**
 * Read the value node `node` carries into `value_out`.
 *
 * # Safety
 * `value_out` points to at least `value_len` bytes.
 */
int32_t subetha_graph_node_value(subetha_handle handle,
                                 uint32_t node,
                                 uint8_t *value_out,
                                 uint64_t value_len);

/**
 * Read the value edge `edge` carries into `value_out`, and write the node
 * it points at into `dst_out`.
 *
 * # Safety
 * `value_out` points to at least `value_len` bytes; `dst_out` is valid.
 */
int32_t subetha_graph_edge_target(subetha_handle handle,
                                  uint32_t edge,
                                  uint8_t *value_out,
                                  uint64_t value_len,
                                  uint32_t *dst_out);

/**
 * How many edges leave `node`, into `degree_out`.
 *
 * # Safety
 * `degree_out` is a valid pointer.
 */
int32_t subetha_graph_out_degree(subetha_handle handle, uint32_t node, uint32_t *degree_out);

/**
 * The first edge leaving `node`, into `edge_out`, or `SUBETHA_GRAPH_NIL`
 * where it has none.
 *
 * # Safety
 * `edge_out` is a valid pointer.
 */
int32_t subetha_graph_first_edge(subetha_handle handle, uint32_t node, uint32_t *edge_out);

/**
 * The edge after `edge` in the same source's chain, into `edge_out`, or
 * `SUBETHA_GRAPH_NIL` at the end.
 *
 * # Safety
 * `edge_out` is a valid pointer.
 */
int32_t subetha_graph_next_edge(subetha_handle handle, uint32_t edge, uint32_t *edge_out);

/**
 * Remove `edge` from `src`'s chain and free its slot.
 *
 * Refused where `src` does not own that edge, since freeing it would
 * leave whichever chain does own it pointing at a free slot.
 */
int32_t subetha_graph_remove_edge(subetha_handle handle, uint32_t src, uint32_t edge);

/**
 * Read the graph's shape and occupancy into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_graph_read_stats(subetha_handle handle, struct subetha_graph_stats *out);

/**
 * Push both of the graph's files to disk and wait for them.
 */
int32_t subetha_graph_flush(subetha_handle handle);

/**
 * Create an LRU cache under `base_path`, holding `capacity` entries of
 * `key_size` and `value_size` bytes.
 *
 * One file is made beside that prefix, holding the index and the entries.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_lru_create(const char *base_path,
                           uint32_t capacity,
                           uint64_t key_size,
                           uint64_t value_size,
                           uint32_t mode,
                           subetha_handle *out);

/**
 * Attach to a cache another process created under `base_path`. The file
 * must exist and have been built with the same shape.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_lru_open(const char *base_path,
                         uint32_t capacity,
                         uint64_t key_size,
                         uint64_t value_size,
                         uint32_t mode,
                         subetha_handle *out);

/**
 * Store `value` under `key`, marked referenced, evicting first where the
 * cache is full and the key is new.
 *
 * `replaced` is set to true where the key was already present and its
 * value overwritten. It may be null when the caller does not care.
 *
 * # Safety
 * `key` and `value` point to at least their declared sizes; `replaced` is
 * null or a valid pointer.
 */
int32_t subetha_lru_put(subetha_handle handle,
                        const uint8_t *key,
                        uint64_t key_len,
                        const uint8_t *value,
                        uint64_t value_len,
                        bool *replaced);

/**
 * Read the value for `key` into `value_out`, leaving its mark as it was.
 *
 * `found` is set to whether the cache held it. When it did not, nothing
 * is written to `value_out`.
 *
 * # Safety
 * `key` and `value_out` point to at least their declared sizes; `found`
 * is a valid pointer.
 */
int32_t subetha_lru_get(subetha_handle handle,
                        const uint8_t *key,
                        uint64_t key_len,
                        uint8_t *value_out,
                        uint64_t value_len,
                        bool *found);

/**
 * Read the value for `key` into `value_out` and mark it referenced, so
 * eviction passes it once.
 *
 * # Safety
 * As [`subetha_lru_get`].
 */
int32_t subetha_lru_get_and_touch(subetha_handle handle,
                                  const uint8_t *key,
                                  uint64_t key_len,
                                  uint8_t *value_out,
                                  uint64_t value_len,
                                  bool *found);

/**
 * Whether the cache holds `key`, leaving its mark as it was.
 *
 * # Safety
 * `key` points to at least `key_len` bytes; `present` is a valid pointer.
 */
int32_t subetha_lru_contains(subetha_handle handle,
                             const uint8_t *key,
                             uint64_t key_len,
                             bool *present);

/**
 * Mark `key` referenced, so eviction passes it once, without reading its
 * value.
 *
 * `touched` is set to whether the cache held it, and may be null.
 *
 * # Safety
 * `key` points to at least `key_len` bytes; `touched` is null or valid.
 */
int32_t subetha_lru_touch(subetha_handle handle,
                          const uint8_t *key,
                          uint64_t key_len,
                          bool *touched);

/**
 * Drop `key`, writing its value into `value_out`.
 *
 * `removed` is set to whether the cache held it. When it did not,
 * nothing is written to `value_out`.
 *
 * # Safety
 * `key` and `value_out` point to at least their declared sizes;
 * `removed` is a valid pointer.
 */
int32_t subetha_lru_remove(subetha_handle handle,
                           const uint8_t *key,
                           uint64_t key_len,
                           uint8_t *value_out,
                           uint64_t value_len,
                           bool *removed);

/**
 * Evict the entry eviction reaches first unmarked, writing its key and
 * value out.
 *
 * `evicted` is set to whether there was anything to evict.
 *
 * # Safety
 * `key_out` and `value_out` point to at least their declared sizes;
 * `evicted` is a valid pointer.
 */
int32_t subetha_lru_evict_oldest(subetha_handle handle,
                                 uint8_t *key_out,
                                 uint64_t key_len,
                                 uint8_t *value_out,
                                 uint64_t value_len,
                                 bool *evicted);

/**
 * Read the cache's shape and occupancy into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_lru_read_stats(subetha_handle handle, struct subetha_lru_stats *out);

/**
 * Push the cache's file to disk and wait for it.
 */
int32_t subetha_lru_flush(subetha_handle handle);

/**
 * The nil value.
 */
uint64_t subetha_nan_nil(void);

/**
 * Pack a double.
 *
 * A NaN going in comes back as the one canonical quiet NaN, so its bits
 * can never be mistaken for a boxed value. That means a caller cannot
 * round-trip a particular NaN payload through here: every NaN is the
 * same NaN afterward.
 */
uint64_t subetha_nan_from_f64(double value);

/**
 * Pack a signed 32-bit integer.
 */
uint64_t subetha_nan_from_i32(int32_t value);

/**
 * Pack an unsigned 32-bit integer.
 */
uint64_t subetha_nan_from_u32(uint32_t value);

/**
 * Pack a boolean.
 */
uint64_t subetha_nan_from_bool(bool value);

/**
 * Which of the `SUBETHA_NAN_` kinds `value` holds.
 */
uint32_t subetha_nan_type(uint64_t value);

/**
 * Read `value` as a double, into `out`. Answers false and writes nothing
 * when it holds something else.
 *
 * # Safety
 * `out` is null or a valid pointer.
 */
bool subetha_nan_as_f64(uint64_t value, double *out);

/**
 * Read `value` as a signed 32-bit integer, into `out`. Answers false and
 * writes nothing when it holds something else.
 *
 * # Safety
 * `out` is null or a valid pointer.
 */
bool subetha_nan_as_i32(uint64_t value, int32_t *out);

/**
 * Read `value` as an unsigned 32-bit integer, into `out`. Answers false
 * and writes nothing when it holds something else.
 *
 * # Safety
 * `out` is null or a valid pointer.
 */
bool subetha_nan_as_u32(uint64_t value, uint32_t *out);

/**
 * Read `value` as a boolean, into `out`. Answers false and writes
 * nothing when it holds something else.
 *
 * Note that a false answer and a stored `false` are different things:
 * the answer says whether the word held a boolean at all, and `out`
 * says which boolean it was.
 *
 * # Safety
 * `out` is null or a valid pointer.
 */
bool subetha_nan_as_bool(uint64_t value, bool *out);

/**
 * Whether `value` is nil.
 */
bool subetha_nan_is_nil(uint64_t value);

/**
 * Pack an index and a tag into one word, as a two-level value: the outer
 * tag says it is a tagged pointer, and `tag_bits` of the payload hold
 * the inner tag with the rest holding the index.
 *
 * `tag_bits` is not stored in the word. A caller reading it back must
 * pass the same width it wrote, and nothing here can check that: a wrong
 * width yields a different index and tag rather than a refusal.
 *
 * Answers false and writes nothing when `tag_bits` is above
 * `SUBETHA_NAN_MAX_TAG_BITS`, or when either component does not fit the
 * width it leaves. A component is refused rather than truncated, since a
 * silently narrowed index points somewhere else.
 *
 * # Safety
 * `out` is null or a valid pointer.
 */
bool subetha_nan_from_tagged(uint32_t index, uint32_t tag, uint32_t tag_bits, uint64_t *out);

/**
 * Read `value` as an index and a tag at `tag_bits`.
 *
 * Answers false and writes nothing when the word is not a tagged
 * pointer, or `tag_bits` is above `SUBETHA_NAN_MAX_TAG_BITS`.
 *
 * # Safety
 * `index_out` and `tag_out` are each null or a valid pointer.
 */
bool subetha_nan_as_tagged(uint64_t value,
                           uint32_t tag_bits,
                           uint32_t *index_out,
                           uint32_t *tag_out);

/**
 * Whether `value` is a tagged pointer.
 *
 * A word packed by `subetha_nan_from_tagged` reads as
 * `SUBETHA_NAN_RESERVED` from `subetha_nan_type`, which knows only the
 * one-level form. This is how the two-level form is recognized.
 */
bool subetha_nan_is_tagged(uint64_t value);

/**
 * Create a tile at `path` whose lanes carry `payload_size` bytes, at most
 * `SUBETHA_TILE_MAX_PAYLOAD`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_tile_create(const char *path,
                            uint64_t payload_size,
                            uint32_t mode,
                            subetha_handle *out);

/**
 * Attach to a tile another process created. Its header must agree about
 * the payload size, since otherwise the two callers would disagree about
 * how many of a lane's bytes mean anything.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_tile_open(const char *path,
                          uint64_t payload_size,
                          uint32_t mode,
                          subetha_handle *out);

/**
 * Publish `value` at `version`, writing the lane it took into `lane_out`.
 *
 * `version` must not be zero. The payload reaches the lane before the
 * version does, so a reader that sees the version sees the whole payload.
 *
 * # Safety
 * `value` points to at least `value_len` bytes; `lane_out` is valid.
 */
int32_t subetha_tile_insert(subetha_handle handle,
                            uint64_t version,
                            const uint8_t *value,
                            uint64_t value_len,
                            uint32_t *lane_out);

/**
 * Free `lane`.
 *
 * The version is cleared before the lane is released, so a lane reclaimed
 * afterward cannot be seen through its predecessor's version.
 */
int32_t subetha_tile_remove(subetha_handle handle, uint32_t lane);

/**
 * Read the payload at `lane` into `value_out` and its version into
 * `version_out`.
 *
 * `present` is set to whether the lane holds a published value. A lane
 * that is claimed but not yet published reads as absent, which is what
 * keeps a half-written payload from being seen.
 *
 * # Safety
 * `value_out` points to at least `value_len` bytes; `version_out` and
 * `present` are valid pointers.
 */
int32_t subetha_tile_at(subetha_handle handle,
                        uint32_t lane,
                        uint8_t *value_out,
                        uint64_t value_len,
                        uint64_t *version_out,
                        bool *present);

/**
 * A bit per lane visible at `snapshot`, into `mask_out`.
 *
 * Bit `n` is set when lane `n` is occupied, published, and carries a
 * version no greater than `snapshot`. The boundary is inclusive.
 *
 * # Safety
 * `mask_out` is a valid pointer.
 */
int32_t subetha_tile_visible_mask(subetha_handle handle, uint64_t snapshot, uint32_t *mask_out);

/**
 * How many lanes `snapshot` sees, into `count_out`.
 *
 * # Safety
 * `count_out` is a valid pointer.
 */
int32_t subetha_tile_visible_count(subetha_handle handle, uint64_t snapshot, uint32_t *count_out);

/**
 * Read the tile's shape and occupancy into `out`.
 *
 * `len` counts occupied lanes whether or not any snapshot can see them,
 * so it can exceed what `subetha_tile_visible_count` answers.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_tile_read_stats(subetha_handle handle, struct subetha_tile_stats *out);

/**
 * Push the tile to disk and wait for it.
 */
int32_t subetha_tile_flush(subetha_handle handle);

/**
 * The four-byte prefix `value` would carry, without storing anything.
 *
 * Lets a caller compute a query prefix once and test many pointers
 * against it with `subetha_umbra_matches_prefix`.
 *
 * # Safety
 * `value` points to at least `value_len` bytes; `prefix_out` is valid.
 */
int32_t subetha_umbra_content_prefix(const uint8_t *value,
                                     uint64_t value_len,
                                     uint32_t *prefix_out);

/**
 * A pointer at nothing, into `out`.
 *
 * # Safety
 * `out` points to at least `SUBETHA_UMBRA_BYTES` writable bytes.
 */
int32_t subetha_umbra_nil(uint8_t *out);

/**
 * Store `value` in the region `region` names and write a pointer at it
 * into `out`, taking the prefix from the value's own first four bytes.
 *
 * # Safety
 * `value` points to at least `value_len` bytes; `out` points to at least
 * `SUBETHA_UMBRA_BYTES` writable bytes.
 */
int32_t subetha_umbra_allocate(subetha_handle region,
                               const uint8_t *value,
                               uint64_t value_len,
                               uint8_t *out);

/**
 * Store `value` and write a pointer at it carrying `prefix`, rather than
 * one taken from the bytes.
 *
 * For a record opening with a header its first four bytes share with
 * every other record, a caller-chosen prefix is what makes the filter
 * worth having at all.
 *
 * # Safety
 * As [`subetha_umbra_allocate`].
 */
int32_t subetha_umbra_allocate_with_prefix(subetha_handle region,
                                           const uint8_t *value,
                                           uint64_t value_len,
                                           uint32_t prefix,
                                           uint8_t *out);

/**
 * Read the value `pointer` names into `value_out`.
 *
 * # Safety
 * `pointer` points to at least `SUBETHA_UMBRA_BYTES` readable bytes;
 * `value_out` points to at least `value_len` writable bytes.
 */
int32_t subetha_umbra_resolve(subetha_handle region,
                              const uint8_t *pointer,
                              uint8_t *value_out,
                              uint64_t value_len);

/**
 * The slot `pointer` names, into `target_out`, or `SUBETHA_UMBRA_NIL`.
 *
 * # Safety
 * `pointer` points to at least `SUBETHA_UMBRA_BYTES` readable bytes;
 * `target_out` is a valid pointer.
 */
int32_t subetha_umbra_target(const uint8_t *pointer, uint32_t *target_out);

/**
 * The prefix `pointer` carries, into `prefix_out`.
 *
 * # Safety
 * `pointer` points to at least `SUBETHA_UMBRA_BYTES` readable bytes;
 * `prefix_out` is a valid pointer.
 */
int32_t subetha_umbra_prefix(const uint8_t *pointer, uint32_t *prefix_out);

/**
 * Whether `pointer` aims at nothing, into `nil_out`.
 *
 * # Safety
 * `pointer` points to at least `SUBETHA_UMBRA_BYTES` readable bytes;
 * `nil_out` is a valid pointer.
 */
int32_t subetha_umbra_is_nil(const uint8_t *pointer, bool *nil_out);

/**
 * Whether two pointers could aim at equal values, into `equal_out`.
 *
 * A false answer is certain. A true answer means resolve both and
 * compare: four bytes agreeing is not equality.
 *
 * # Safety
 * Both pointers point to at least `SUBETHA_UMBRA_BYTES` readable bytes;
 * `equal_out` is a valid pointer.
 */
int32_t subetha_umbra_prefix_eq(const uint8_t *left, const uint8_t *right, bool *equal_out);

/**
 * Whether `pointer` could aim at a value starting with `query`, into
 * `matches_out`.
 *
 * # Safety
 * `pointer` points to at least `SUBETHA_UMBRA_BYTES` readable bytes;
 * `matches_out` is a valid pointer.
 */
int32_t subetha_umbra_matches_prefix(const uint8_t *pointer, uint32_t query, bool *matches_out);

/**
 * Attach a caller tag and up to `SUBETHA_UMBRA_EXT_BYTES` of payload,
 * writing the changed pointer back into `pointer`.
 *
 * A payload longer than that is refused and the pointer is left alone.
 *
 * # Safety
 * `pointer` points to at least `SUBETHA_UMBRA_BYTES` bytes readable and
 * writable; `payload` points to at least `payload_len` bytes.
 */
int32_t subetha_umbra_set_ext(uint8_t *pointer,
                              uint8_t tag,
                              const uint8_t *payload,
                              uint64_t payload_len);

/**
 * The tag and payload `pointer` carries.
 *
 * The payload bytes are handed over whatever the tag says; a caller that
 * has not checked the tag is reading bytes whose meaning nobody agreed.
 *
 * # Safety
 * `pointer` points to at least `SUBETHA_UMBRA_BYTES` readable bytes;
 * `tag_out` is valid; `payload_out` points to at least
 * `SUBETHA_UMBRA_EXT_BYTES` writable bytes.
 */
int32_t subetha_umbra_get_ext(const uint8_t *pointer, uint8_t *tag_out, uint8_t *payload_out);

/**
 * Drop any caller tag and zero its payload, writing the changed pointer
 * back into `pointer`.
 *
 * # Safety
 * `pointer` points to at least `SUBETHA_UMBRA_BYTES` bytes readable and
 * writable.
 */
int32_t subetha_umbra_clear_ext(uint8_t *pointer);

/**
 * Obtain the set under `base_path` holding up to `capacity` elements of
 * `element_size` bytes: a new one starts on `strategy` with no tables but
 * its own, and one that already exists keeps the strategy in force, which
 * lives in a state file beside its tables and is what every handle reads.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_universal_create(const char *base_path,
                                 uint64_t capacity,
                                 uint64_t element_size,
                                 uint32_t strategy,
                                 uint32_t mode,
                                 subetha_handle *out);

/**
 * Attach to a set another process created under `base_path`. The
 * strategy in force is read from the set's state file, so this handle
 * holds no belief of its own; a migration through any handle is what
 * this one reads on its next call, and the stamp in the stats says when
 * that happened.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_universal_open(const char *base_path,
                               uint64_t capacity,
                               uint64_t element_size,
                               uint32_t mode,
                               subetha_handle *out);

/**
 * Add `value` if it is not already present.
 *
 * `added` is set to true when it was added and false when the set
 * already held it; of several handles adding one value at once, in any
 * processes, exactly one is told it was added. It may be null when the
 * caller does not care.
 *
 * # Safety
 * `value` points to at least `value_len` bytes; `added` is null or valid.
 */
int32_t subetha_universal_insert(subetha_handle handle,
                                 const uint8_t *value,
                                 uint64_t value_len,
                                 bool *added);

/**
 * Whether the set holds `value`, into `present`.
 *
 * # Safety
 * `value` points to at least `value_len` bytes; `present` is valid.
 */
int32_t subetha_universal_contains(subetha_handle handle,
                                   const uint8_t *value,
                                   uint64_t value_len,
                                   bool *present);

/**
 * Move the set to `strategy`, carrying every element across.
 *
 * The live round is sealed first; another handle adding meanwhile runs
 * the move to its end and adds to the round after, and the stamp moves
 * only once every element published before the seal is copied into the
 * next round of the other table, so a reader whose stamp is unchanged
 * read one round throughout. Migrating to the strategy already in force
 * changes nothing and does not advance the stamp.
 * `SUBETHA_E_WOULD_BLOCK` when another process's move sealed the set
 * first; that move is run to its end before this returns, and the set is
 * on the table it chose.
 */
int32_t subetha_universal_migrate(subetha_handle handle, uint32_t strategy);

/**
 * Empty the set: it moves to the next round of its own table, which
 * starts empty, so the stamp moves as for a migration. An element added
 * while the clear runs is kept or dropped as a whole.
 */
int32_t subetha_universal_clear(subetha_handle handle);

/**
 * Read the strategy word, the counts and the occupancy into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_universal_read_stats(subetha_handle handle, struct subetha_universal_stats *out);

/**
 * Push the live table and the state file to disk and wait for them.
 */
int32_t subetha_universal_flush(subetha_handle handle);

/**
 * Remove every file of the set under `base_path`: its state file and each
 * table. The contract is `subetha_ring_unlink`'s.
 *
 * # Safety
 * `base_path` is a NUL-terminated UTF-8 string; `report` is null or a
 * valid pointer.
 */
int32_t subetha_universal_unlink(const char *base_path, struct subetha_unlink_report *report);

/**
 * Create a tower whose leaf at `leaf_path` holds `leaf_capacity` values
 * of `value_size` bytes, with one intermediate level per entry in
 * `level_paths` / `level_capacities`, top first.
 *
 * Depth is `n_levels + 1`. Zero levels makes a depth-1 tower, which is a
 * bare region with a one-entry path.
 *
 * # Safety
 * `leaf_path` is a NUL-terminated UTF-8 string; `level_paths` points to
 * `n_levels` such strings and `level_capacities` to `n_levels` values;
 * `out` is a valid pointer.
 */
int32_t subetha_tower_create(const char *leaf_path,
                             uint64_t leaf_capacity,
                             uint64_t value_size,
                             const char *const *level_paths,
                             const uint64_t *level_capacities,
                             uint64_t n_levels,
                             uint32_t mode,
                             subetha_handle *out);

/**
 * Attach to a tower another process created, with the same shape.
 *
 * # Safety
 * As [`subetha_tower_create`].
 */
int32_t subetha_tower_open(const char *leaf_path,
                           uint64_t leaf_capacity,
                           uint64_t value_size,
                           const char *const *level_paths,
                           const uint64_t *level_capacities,
                           uint64_t n_levels,
                           uint32_t mode,
                           subetha_handle *out);

/**
 * Store `value` and hang it off the next free slot on the top level,
 * writing the path into `path_out`, which must hold exactly `depth`
 * entries.
 *
 * # Safety
 * `value` points to at least `value_len` bytes; `path_out` points to at
 * least `path_len` writable `u32`s.
 */
int32_t subetha_tower_append(subetha_handle handle,
                             const uint8_t *value,
                             uint64_t value_len,
                             uint32_t *path_out,
                             uint64_t path_len);

/**
 * Store `value` and build the chain of links down to it from `top_slot`
 * on the top level, writing the path into `path_out`.
 *
 * The leaf is written first and the top link last, so a reader walking
 * down never reaches a level that does not yet name a live slot below.
 *
 * # Safety
 * As [`subetha_tower_append`].
 */
int32_t subetha_tower_insert_at_top(subetha_handle handle,
                                    uint32_t top_slot,
                                    const uint8_t *value,
                                    uint64_t value_len,
                                    uint32_t *path_out,
                                    uint64_t path_len);

/**
 * Read the value `path` names into `value_out`, checking every level.
 *
 * Refused with the level that failed rather than resolving a path the
 * tower no longer agrees with, and nothing is written on a refusal.
 *
 * # Safety
 * `path` points to at least `path_len` readable `u32`s; `value_out`
 * points to at least `value_len` writable bytes.
 */
int32_t subetha_tower_get(subetha_handle handle,
                          const uint32_t *path,
                          uint64_t path_len,
                          uint8_t *value_out,
                          uint64_t value_len);

/**
 * Read the tower's shape and occupancy into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_tower_read_stats(subetha_handle handle, struct subetha_tower_stats *out);

/**
 * Push every level to disk and wait for them.
 */
int32_t subetha_tower_flush(subetha_handle handle);

/**
 * Make a policy from one of the `SUBETHA_QOS_PRESET_` constants.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_qos_create_preset(uint32_t preset, uint32_t mode, subetha_handle *out);

/**
 * Make a policy from every field at once. Every field is validated
 * before anything is built, so a refusal leaves no handle.
 *
 * # Safety
 * `initial` and `out` are valid pointers.
 */
int32_t subetha_qos_create(const struct subetha_qos *initial, uint32_t mode, subetha_handle *out);

/**
 * Read the whole policy into `out`.
 *
 * Five atomics are read one after another, so a writer running during
 * this can leave a mixture of two policies: every field was real, the
 * combination need not have been.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_qos_read(subetha_handle handle, struct subetha_qos *out);

/**
 * Set the durability. Atomic on its own.
 */
int32_t subetha_qos_set_durability(subetha_handle handle, uint32_t durability);

/**
 * Set the reliability. Atomic on its own.
 */
int32_t subetha_qos_set_reliability(subetha_handle handle, uint32_t reliability);

/**
 * Set the history. `depth` is read only for `SUBETHA_QOS_KEEP_LAST`, and
 * a depth of zero there is refused rather than kept as a policy that
 * keeps nothing. Atomic on its own: the kind and the depth share one
 * word.
 */
int32_t subetha_qos_set_history(subetha_handle handle, uint32_t kind, uint32_t depth);

/**
 * Set the latency budget in nanoseconds. Atomic on its own.
 */
int32_t subetha_qos_set_max_latency(subetha_handle handle, uint64_t nanos);

/**
 * Set the ordering. Atomic on its own.
 */
int32_t subetha_qos_set_ordering(subetha_handle handle, uint32_t ordering);

/**
 * The locale this policy's durability asks for, into `out`, as one of the
 * `SUBETHA_LOCALE_` constants.
 *
 * It is a recommendation, not a move: a ring changes locale when a caller
 * tells it to.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_qos_recommended_locale(subetha_handle handle, uint32_t *out);

/**
 * The ring capacity this policy's history asks for, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_qos_recommended_capacity(subetha_handle handle, uint64_t *out);

/**
 * The mode this policy was created in, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_qos_mode(subetha_handle handle, uint32_t *out);

/**
 * Make a registry. `mode` is one of the `SUBETHA_MODE_` constants and is
 * recorded rather than acted on, since a registry runs nothing.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_endpoint_registry_create(uint32_t mode, subetha_handle *out);

/**
 * Bind `id` to the locale-adaptive ring `ring` names. Binding an id that
 * is already bound replaces it and steps the generation, which is how a
 * rebind reaches a caller holding an older reading.
 * The ring is taken before the registry is borrowed, and not inside that
 * borrow: a borrow of the handle table does not nest, so holding one
 * while asking for another refuses the second.
 */
int32_t subetha_endpoint_bind_local(subetha_handle registry, uint64_t id, subetha_handle ring);

/**
 * Bind `id` to a remote host: `server_addr` is where its bridge listens
 * and `server_name` is the identity its certificate must carry.
 *
 * Binding a remote target needs no transport built into this library. It
 * records where the bytes would go; carrying them is the bridge's job and
 * its feature's.
 *
 * # Safety
 * `server_addr` and `server_name` are NUL-terminated UTF-8 strings.
 */
int32_t subetha_endpoint_bind_remote(subetha_handle registry,
                                     uint64_t id,
                                     const char *server_addr,
                                     const char *server_name);

/**
 * Remove `id`. `SUBETHA_E_MAP_KEY_ABSENT` when it named nothing, so a caller
 * can tell an unbind that did something from one that did not.
 */
int32_t subetha_endpoint_unbind(subetha_handle registry, uint64_t id);

/**
 * Read what `id` resolves to, and the generation it was read at, into
 * `out`.
 *
 * An unbound id is not an error: it reports `SUBETHA_ENDPOINT_NONE` with
 * a generation, because "nothing is bound here right now" is an answer a
 * caller acts on and can also go stale.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_endpoint_read(subetha_handle registry,
                              uint64_t id,
                              struct subetha_endpoint_target *out);

/**
 * Copy the address and name of a remote binding out as text.
 *
 * `SUBETHA_E_MAP_KEY_ABSENT` when `id` is unbound, `SUBETHA_E_WRONG_KIND` when
 * it names a local ring, and `SUBETHA_E_BUFFER_TOO_SMALL` when a buffer
 * is short, with the needed length written so a caller can ask again.
 *
 * # Safety
 * `addr_out` points to `addr_cap` writable bytes and `name_out` to
 * `name_cap`; both length pointers are valid.
 */
int32_t subetha_endpoint_read_remote(subetha_handle registry,
                                     uint64_t id,
                                     uint8_t *addr_out,
                                     size_t addr_cap,
                                     size_t *addr_len,
                                     uint8_t *name_out,
                                     size_t name_cap,
                                     size_t *name_len);

/**
 * Whether a generation read earlier still stands, into `out`.
 *
 * False means something was bound or unbound since, so anything read at
 * that generation is to be read again. It does not mean this id changed:
 * the counter is registry-wide, so a rebind of another id also moves it.
 * Re-reading is cheap and being wrong is not.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_endpoint_still_valid(subetha_handle registry, uint64_t generation, bool *out);

/**
 * The registry's current generation into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_endpoint_generation(subetha_handle registry, uint64_t *out);

/**
 * How many ids are bound, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_endpoint_count(subetha_handle registry, uint64_t *out);

/**
 * The mode this registry was created in, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_endpoint_registry_mode(subetha_handle registry, uint32_t *out);

/**
 * Create a blocking MPSC pool in anonymous memory: `n_producers` rings of
 * `capacity` slots, one producer handle each into `out_producers`, and
 * the consumer handle into `out_consumer`.
 *
 * # Safety
 * `out_producers` points to `n_producers` writable handles; `out_consumer`
 * is a valid pointer.
 */
int32_t subetha_mpsc_create_anon_pool(uint32_t n_producers,
                                      uint32_t capacity,
                                      uint32_t mode,
                                      subetha_handle *out_producers,
                                      subetha_handle *out_consumer);

/**
 * Create a file-backed blocking MPSC pool under `path_prefix`.
 *
 * # Safety
 * `path_prefix` is a NUL-terminated UTF-8 string; `out_producers` points
 * to `n_producers` writable handles; `out_consumer` is a valid pointer.
 */
int32_t subetha_mpsc_create_pool(const char *path_prefix,
                                 uint32_t n_producers,
                                 uint32_t capacity,
                                 uint32_t mode,
                                 subetha_handle *out_producers,
                                 subetha_handle *out_consumer);

/**
 * Attach to a file-backed blocking MPSC pool another process created
 * under `path_prefix`, with the producer count and capacity it was
 * created with.
 *
 * # Safety
 * `path_prefix` is a NUL-terminated UTF-8 string; `out_producers` points
 * to `n_producers` writable handles; `out_consumer` is a valid pointer.
 */
int32_t subetha_mpsc_open_pool(const char *path_prefix,
                               uint32_t n_producers,
                               uint32_t expected_capacity,
                               uint32_t mode,
                               subetha_handle *out_producers,
                               subetha_handle *out_consumer);

/**
 * Push `len` bytes into this producer's ring without waiting; the slot
 * semantics are the adaptive ring's. `SUBETHA_E_RING_FULL` when there is
 * no room.
 *
 * # Safety
 * `data` points to `len` readable bytes.
 */
int32_t subetha_mpsc_try_push(subetha_handle handle, const uint8_t *data, size_t len);

/**
 * Push, parking until this producer's ring has room or `timeout_ms`
 * elapses; the waiting contract is `subetha_ring_push_wait`'s.
 *
 * # Safety
 * `data` points to `len` readable bytes.
 */
int32_t subetha_mpsc_push_wait(subetha_handle handle,
                               const uint8_t *data,
                               size_t len,
                               int64_t timeout_ms);

/**
 * Push `count` payloads of `len` bytes each onto this producer's ring,
 * the first at `items` and each next one `stride` bytes on, under one
 * handle lookup and one panic guard. The batch contract is
 * `subetha_ring_try_push_many`'s.
 *
 * # Safety
 * `items` addresses `count * stride` readable bytes; `out_done` is a
 * valid pointer.
 */
int32_t subetha_mpsc_try_push_many(subetha_handle handle,
                                   const uint8_t *items,
                                   size_t stride,
                                   size_t len,
                                   size_t count,
                                   size_t *out_done);

/**
 * Pop up to `count` slots from the pool, the first written at `out` and
 * each next one `stride` bytes on. The batch contract is
 * `subetha_ring_try_pop_many`'s.
 *
 * # Safety
 * `out` addresses `count * stride` writable bytes; `out_done` is a valid
 * pointer.
 */
int32_t subetha_mpsc_try_pop_many(subetha_handle handle,
                                  uint8_t *out,
                                  size_t stride,
                                  size_t count,
                                  size_t *out_done);

/**
 * Pop one slot from whichever ring has one, round robin, without waiting;
 * `cap` must be at least `SUBETHA_RING_SLOT_BYTES`. `SUBETHA_E_RING_EMPTY`
 * when every ring is empty.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_mpsc_try_pop(subetha_handle handle, uint8_t *out, size_t cap, size_t *out_len);

/**
 * Pop, parking until any producer pushes or `timeout_ms` elapses; the
 * waiting contract is `subetha_ring_pop_wait`'s.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_mpsc_pop_wait(subetha_handle handle,
                              uint8_t *out,
                              size_t cap,
                              size_t *out_len,
                              int64_t timeout_ms);

/**
 * A snapshot of one producer into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_mpsc_producer_read_stats(subetha_handle handle,
                                         struct subetha_mpsc_producer_stats *out);

/**
 * A snapshot of the consumer into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_mpsc_consumer_read_stats(subetha_handle handle,
                                         struct subetha_mpsc_consumer_stats *out);

/**
 * Remove every file a file-backed blocking MPSC pool under `path_prefix`
 * names, for the producer count it was created with. The contract is
 * `subetha_ring_unlink`'s.
 *
 * # Safety
 * `path_prefix` is a NUL-terminated UTF-8 string; `report` is null or a
 * valid pointer.
 */
int32_t subetha_mpsc_unlink(const char *path_prefix,
                            uint32_t n_producers,
                            struct subetha_unlink_report *report);

/**
 * Create the deque at `path` as its owner, truncating any file there.
 * `capacity` is a power of two of at least 1; the calling process is
 * recorded as the owner, and single-owner discipline is the caller's
 * contract. `scan_interval_us` in the options is ignored, the deque has
 * no sidecar.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `layout`, `options` and `out`
 * are valid pointers.
 */
int32_t subetha_deque_create(const char *path,
                             uint32_t capacity,
                             const struct subetha_element_layout *layout,
                             const struct subetha_ring_options *options,
                             subetha_handle *out);

/**
 * Open the deque another process created at `path` as a thief: the
 * handle steals, and its push and pop return
 * `SUBETHA_E_DEQUE_NOT_OWNER`. `SUBETHA_E_IO` names an absent file
 * and `SUBETHA_E_LAYOUT_MISMATCH` one of another layout.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `layout`, `options` and `out`
 * are valid pointers.
 */
int32_t subetha_deque_open_thief(const char *path,
                                 const struct subetha_element_layout *layout,
                                 const struct subetha_ring_options *options,
                                 subetha_handle *out);

/**
 * Owner side: push up to `element_size` bytes onto the bottom without
 * waiting; the slot is zero past the payload. `SUBETHA_E_RING_FULL` when
 * the deque is at capacity, `SUBETHA_E_RING_PAYLOAD_TOO_LARGE` for more
 * bytes than an element, `SUBETHA_E_DEQUE_NOT_OWNER` from a thief.
 *
 * # Safety
 * `data` points to `len` readable bytes.
 */
int32_t subetha_deque_try_push(subetha_handle handle, const uint8_t *data, size_t len);

/**
 * Owner side: push `count` elements of `len` bytes each, the first at
 * `items` and each next one `stride` bytes on, under one handle lookup
 * and one panic guard. The batch contract is
 * `subetha_ring_try_push_many`'s; a thief's handle is
 * `SUBETHA_E_DEQUE_NOT_OWNER` before anything is pushed.
 *
 * # Safety
 * `items` addresses `count * stride` readable bytes; `out_done` is a
 * valid pointer.
 */
int32_t subetha_deque_try_push_many(subetha_handle handle,
                                    const uint8_t *items,
                                    size_t stride,
                                    size_t len,
                                    size_t count,
                                    size_t *out_done);

/**
 * Thief side: steal up to `count` elements, the first written at `out`
 * and each next one `stride` bytes on; `stride` is at least the element
 * size. The batch contract is `subetha_ring_try_pop_many`'s.
 *
 * # Safety
 * `out` addresses `count * stride` writable bytes; `out_done` is a valid
 * pointer.
 */
int32_t subetha_deque_try_steal_many(subetha_handle handle,
                                     uint8_t *out,
                                     size_t stride,
                                     size_t count,
                                     size_t *out_done);

/**
 * Owner side: push, parking until a steal makes room or `timeout_ms`
 * elapses; the waiting contract is `subetha_ring_push_wait`'s.
 *
 * # Safety
 * `data` points to `len` readable bytes.
 */
int32_t subetha_deque_push_wait(subetha_handle handle,
                                const uint8_t *data,
                                size_t len,
                                int64_t timeout_ms);

/**
 * Owner side: pop the bottom element, `slot_bytes` bytes, into `out`;
 * `cap` must be at least that. `SUBETHA_E_RING_EMPTY` when the deque is
 * empty or a thief took the last element first,
 * `SUBETHA_E_DEQUE_NOT_OWNER` from a thief.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_deque_try_pop(subetha_handle handle, uint8_t *out, size_t cap, size_t *out_len);

/**
 * Steal the top element, `slot_bytes` bytes, into `out` without waiting;
 * `cap` must be at least that. Any handle steals. `SUBETHA_E_RING_EMPTY`
 * when the deque is empty or another taker won the element.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_deque_try_steal(subetha_handle handle, uint8_t *out, size_t cap, size_t *out_len);

/**
 * Steal, parking until the owner pushes or `timeout_ms` elapses; the
 * waiting contract is `subetha_ring_pop_wait`'s.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_deque_steal_wait(subetha_handle handle,
                                 uint8_t *out,
                                 size_t cap,
                                 size_t *out_len,
                                 int64_t timeout_ms);

/**
 * A snapshot of the deque into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_deque_read_stats(subetha_handle handle, struct subetha_deque_stats *out);

/**
 * Write the deque's dirty pages to its file.
 */
int32_t subetha_deque_flush(subetha_handle handle);

/**
 * Wake every thread parked in a wait on this deque; each re-checks the
 * deque and parks again unless it finds what it waited for.
 */
int32_t subetha_deque_wake_all(subetha_handle handle);

/**
 * Remove the deque file at `path` and its two waker files. The contract
 * is `subetha_ring_unlink`'s.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `report` is null or a valid
 * pointer.
 */
int32_t subetha_deque_unlink(const char *path, struct subetha_unlink_report *report);

/**
 * Obtain the map at `path` for `key_size`-byte keys and `value_size`-byte
 * values, `capacity` slots: an empty one is initialized when the file
 * does not exist, an existing one is attached with its entries in place.
 * A file built with another capacity or other sizes is a
 * `SUBETHA_E_LAYOUT_MISMATCH`. Size the table at twice the entries
 * expected; the probe chain saturates past a load factor of 0.7.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_hashmap_create(const char *path,
                               uint32_t capacity,
                               uint32_t key_size,
                               uint32_t value_size,
                               uint32_t mode,
                               subetha_handle *out);

/**
 * Attach to the map another process created at `path`; the file must
 * exist. `SUBETHA_E_IO` names an absent file.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_hashmap_open(const char *path,
                             uint32_t capacity,
                             uint32_t key_size,
                             uint32_t value_size,
                             uint32_t mode,
                             subetha_handle *out);

/**
 * Truncate the file at `path` and initialize an empty map there,
 * discarding every entry other handles share. On Windows the file must
 * not be mapped by any handle.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_hashmap_reset(const char *path,
                              uint32_t capacity,
                              uint32_t key_size,
                              uint32_t value_size,
                              uint32_t mode,
                              subetha_handle *out);

/**
 * Insert or update `key` with `value`; `out_outcome`, when not null,
 * receives `SUBETHA_MAP_INSERTED` or `SUBETHA_MAP_UPDATED`.
 * `SUBETHA_E_MAP_FULL` when no slot is free.
 *
 * # Safety
 * `key` and `value` point to `key_len` and `value_len` readable bytes;
 * `out_outcome` is null or a valid pointer.
 */
int32_t subetha_hashmap_insert(subetha_handle handle,
                               const uint8_t *key,
                               size_t key_len,
                               const uint8_t *value,
                               size_t value_len,
                               uint32_t *out_outcome);

/**
 * Insert `count` entries from the caller's own two arrays, the key at
 * `keys + i * key_stride` and its value at `values + i * value_stride`.
 * One handle lookup and one panic guard for the run.
 *
 * The keys and the values stay in separate arrays because that is how a
 * caller already has them - a column of each - and packing them into
 * pairs to make one array would cost the copy this call exists to avoid.
 *
 * Whether each entry was new or replaced an existing one is not
 * reported: a run of inserts is a caller saying what the map should
 * hold, and the per-entry outcome is what `subetha_hashmap_insert`
 * answers for a caller that needs it. The batch stops at the first
 * refusal, `SUBETHA_E_MAP_FULL` being the one to expect, and reports how
 * many landed.
 *
 * # Safety
 * `keys` addresses `count * key_stride` readable bytes and `values`
 * `count * value_stride`; `out_done` is a valid pointer.
 */
int32_t subetha_hashmap_insert_many(subetha_handle handle,
                                    const uint8_t *keys,
                                    size_t key_stride,
                                    const uint8_t *values,
                                    size_t value_stride,
                                    size_t count,
                                    size_t *out_done);

/**
 * Read `count` entries into the caller's own array, the value for the
 * key at `keys + i * key_stride` into `out + i * value_stride`. One
 * handle lookup and one panic guard for the run.
 *
 * The batch stops at the first key the map does not hold and reports how
 * many it read, so a caller that wants every hit rather than a run of
 * them looks each up on its own. `SUBETHA_E_MAP_KEY_ABSENT` is what a
 * first miss reports.
 *
 * # Safety
 * `keys` addresses `count * key_stride` readable bytes; `out` addresses
 * `count * value_stride` writable bytes; `out_done` is a valid pointer.
 */
int32_t subetha_hashmap_get_many(subetha_handle handle,
                                 const uint8_t *keys,
                                 size_t key_stride,
                                 uint8_t *out,
                                 size_t value_stride,
                                 size_t count,
                                 size_t *out_done);

/**
 * Insert `key` only if it is absent. `out_present` receives whether a
 * value was already there, in which case nothing was written and that
 * value was copied into `existing`, at least `value_size` bytes.
 *
 * # Safety
 * `key` and `value` point to readable bytes; `existing` points to `cap`
 * writable bytes; `existing_len` and `out_present` are valid pointers.
 */
int32_t subetha_hashmap_insert_if_absent(subetha_handle handle,
                                         const uint8_t *key,
                                         size_t key_len,
                                         const uint8_t *value,
                                         size_t value_len,
                                         uint8_t *existing,
                                         size_t cap,
                                         size_t *existing_len,
                                         bool *out_present);

/**
 * Copy `key`'s value into `out`, at least `value_size` bytes;
 * `SUBETHA_E_MAP_KEY_ABSENT` when the key has no entry.
 *
 * # Safety
 * `key` points to `key_len` readable bytes; `out` points to `cap`
 * writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_hashmap_get(subetha_handle handle,
                            const uint8_t *key,
                            size_t key_len,
                            uint8_t *out,
                            size_t cap,
                            size_t *out_len);

/**
 * Whether `key` has an entry.
 *
 * # Safety
 * `key` points to `key_len` readable bytes; `out` is a valid pointer.
 */
int32_t subetha_hashmap_contains(subetha_handle handle,
                                 const uint8_t *key,
                                 size_t key_len,
                                 bool *out);

/**
 * Remove `key`, copying the value it had into `out`, at least
 * `value_size` bytes; `SUBETHA_E_MAP_KEY_ABSENT` when it had none.
 *
 * # Safety
 * `key` points to `key_len` readable bytes; `out` points to `cap`
 * writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_hashmap_remove(subetha_handle handle,
                               const uint8_t *key,
                               size_t key_len,
                               uint8_t *out,
                               size_t cap,
                               size_t *out_len);

/**
 * Replace `key`'s value with `new` only if its current value is
 * byte-for-byte `expected`. `out_swapped` receives whether it was; when
 * it was not, the current value is copied into `current`, at least
 * `value_size` bytes. `SUBETHA_E_MAP_KEY_ABSENT` when the key has no
 * entry. The comparison and the write happen under the entry's lock.
 *
 * # Safety
 * `key`, `expected` and `new` point to readable bytes; `current` points
 * to `cap` writable bytes; `current_len` and `out_swapped` are valid
 * pointers.
 */
int32_t subetha_hashmap_compare_exchange(subetha_handle handle,
                                         const uint8_t *key,
                                         size_t key_len,
                                         const uint8_t *expected,
                                         size_t expected_len,
                                         const uint8_t *new_,
                                         size_t new_len,
                                         uint8_t *current,
                                         size_t cap,
                                         size_t *current_len,
                                         bool *out_swapped);

/**
 * Mark every slot empty. Not safe against an insert or remove running in
 * any process.
 */
int32_t subetha_hashmap_clear(subetha_handle handle);

/**
 * Reclaim the tombstones removes left by rebuilding the table in place;
 * `out_reclaimed`, when not null, receives how many. Not safe against a
 * writer in any process; a reader may miss an entry mid-rebuild.
 *
 * # Safety
 * `out_reclaimed` is null or a valid pointer.
 */
int32_t subetha_hashmap_compact(subetha_handle handle, uint64_t *out_reclaimed);

/**
 * Walk the entries: with `cursor` at zero, the first entry; each call
 * copies one entry's key and value into `key_out` and `value_out` and
 * advances `cursor`. `out_found` receives false, with nothing copied,
 * once the table is walked. An entry is seen once its insert has
 * published it; a slot an insert has claimed and not yet written is
 * passed over, so a walk under concurrent writers sees the entries
 * published before it reached their slots and never a payload still
 * being written. A walker that must see every entry walks again once
 * the writers have returned.
 *
 * # Safety
 * `cursor`, `key_len`, `value_len` and `out_found` are valid pointers;
 * `key_out` and `value_out` point to `key_cap` and `value_cap` writable
 * bytes.
 */
int32_t subetha_hashmap_next(subetha_handle handle,
                             uint64_t *cursor,
                             uint8_t *key_out,
                             size_t key_cap,
                             size_t *key_len,
                             uint8_t *value_out,
                             size_t value_cap,
                             size_t *value_len,
                             bool *out_found);

/**
 * A snapshot of the map into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_hashmap_read_stats(subetha_handle handle, struct subetha_hashmap_stats *out);

/**
 * Write the map's dirty pages to its file.
 */
int32_t subetha_hashmap_flush(subetha_handle handle);

/**
 * Remove the map file at `path`. The contract is `subetha_ring_unlink`'s.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `report` is null or a valid
 * pointer.
 */
int32_t subetha_hashmap_unlink(const char *path, struct subetha_unlink_report *report);

/**
 * Obtain the table at `path` with `capacity` slots: an empty one is
 * initialized when the file does not exist, an existing one is attached
 * with its registered processes in place, so a late joiner does not
 * unregister anyone. A file built with another capacity is a
 * `SUBETHA_E_LAYOUT_MISMATCH`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_heartbeat_create(const char *path,
                                 uint32_t capacity,
                                 uint32_t mode,
                                 subetha_handle *out);

/**
 * Attach to the table another process created at `path`; the file must
 * exist. `SUBETHA_E_IO` names an absent file.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_heartbeat_open(const char *path,
                               uint32_t capacity,
                               uint32_t mode,
                               subetha_handle *out);

/**
 * Truncate the file at `path` and lay out an empty table, unregistering
 * every process that held a slot.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_heartbeat_reset(const char *path,
                                uint32_t capacity,
                                uint32_t mode,
                                subetha_handle *out);

/**
 * Take a free slot for `pid` and write its index into `out_slot`. The
 * index is what every later call about this process uses.
 * `SUBETHA_E_RING_FULL` when every slot is held.
 *
 * # Safety
 * `out_slot` is a valid pointer.
 */
int32_t subetha_heartbeat_register(subetha_handle handle, uint32_t pid, uint32_t *out_slot);

/**
 * Free the slot at `slot`, so another process can take it. A process
 * shutting down cleanly does this rather than leaving a slot for a
 * watcher to reclaim.
 */
int32_t subetha_heartbeat_unregister(subetha_handle handle, uint32_t slot);

/**
 * Stamp the slot at `slot` with the current epoch, which is how its
 * holder says it is still there.
 */
int32_t subetha_heartbeat_beat(subetha_handle handle, uint32_t slot);

/**
 * Advance the global epoch and write it into `out_epoch`. Every grace
 * window is measured against this, so a departed process is only
 * noticed once something ticks it.
 *
 * # Safety
 * `out_epoch` is null or a valid pointer.
 */
int32_t subetha_heartbeat_tick_epoch(subetha_handle handle, uint64_t *out_epoch);

/**
 * Set bit `bit` in the slot's in-flight bitmap, saying its holder has
 * taken that work unit. `bit` runs from zero to one below
 * `SUBETHA_HEARTBEAT_IN_FLIGHT`.
 */
int32_t subetha_heartbeat_mark_in_flight(subetha_handle handle, uint32_t slot, uint32_t bit);

/**
 * Clear bit `bit` in the slot's in-flight bitmap, saying its holder has
 * finished that work unit.
 */
int32_t subetha_heartbeat_clear_in_flight(subetha_handle handle, uint32_t slot, uint32_t bit);

/**
 * Read the slot at `slot` into `out`, every field from one registration.
 * Writes `SUBETHA_HEARTBEAT_EMPTY_PID` into `out->pid` for a slot nobody
 * holds or whose register has not yet published, which is not an error: a
 * watcher walks every slot and reads the empty ones as empty.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_heartbeat_read_slot(subetha_handle handle,
                                    uint32_t slot,
                                    struct subetha_heartbeat_slot *out);

/**
 * A snapshot of the table into `out`. The registered count is a walk of
 * every slot, so it races a register or an unregister in some process.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_heartbeat_read_stats(subetha_handle handle, struct subetha_heartbeat_stats *out);

/**
 * Remove the table's file at `path`. The contract is
 * `subetha_ring_unlink`'s.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `report` is null or a valid
 * pointer.
 */
int32_t subetha_heartbeat_unlink(const char *path, struct subetha_unlink_report *report);

/**
 * Obtain the histogram at `path` with the `n_boundaries` ascending
 * upper bounds at `boundaries`: an empty one is initialized when the
 * file does not exist, an existing one is attached with its counts in
 * place. A histogram built with other boundaries is a
 * `SUBETHA_E_LAYOUT_MISMATCH`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `boundaries` points to
 * `n_boundaries` readable values; `out` is a valid pointer.
 */
int32_t subetha_histogram_create(const char *path,
                                 const uint64_t *boundaries,
                                 size_t n_boundaries,
                                 uint32_t mode,
                                 subetha_handle *out);

/**
 * Attach to the histogram another process created at `path`; the file
 * must exist. `SUBETHA_E_IO` names an absent one.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `boundaries` points to
 * `n_boundaries` readable values; `out` is a valid pointer.
 */
int32_t subetha_histogram_open(const char *path,
                               const uint64_t *boundaries,
                               size_t n_boundaries,
                               uint32_t mode,
                               subetha_handle *out);

/**
 * Record `value`, and report the bucket it landed in through `out_bucket`
 * when that is not null.
 *
 * # Safety
 * `out_bucket` is null or a valid pointer.
 */
int32_t subetha_histogram_record(subetha_handle handle, uint64_t value, uint64_t *out_bucket);

/**
 * The bucket `value` would land in, into `out`, without recording it.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_histogram_bucket_for(subetha_handle handle, uint64_t value, uint64_t *out);

/**
 * The count in bucket `bucket_idx`, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_histogram_count(subetha_handle handle, uint64_t bucket_idx, uint64_t *out);

/**
 * Every bucket's count into `out`, which holds `cap` values, and how many
 * were written into `out_len`. `SUBETHA_E_BUFFER_TOO_SMALL` when `cap` is
 * below the bucket count, with the count needed in `out_len`.
 *
 * # Safety
 * `out` points to `cap` writable values; `out_len` is a valid pointer.
 */
int32_t subetha_histogram_counts(subetha_handle handle, uint64_t *out, size_t cap, size_t *out_len);

/**
 * The boundaries the histogram was built with into `out`, the same way
 * `subetha_histogram_counts` reports counts.
 *
 * # Safety
 * `out` points to `cap` writable values; `out_len` is a valid pointer.
 */
int32_t subetha_histogram_boundaries(subetha_handle handle,
                                     uint64_t *out,
                                     size_t cap,
                                     size_t *out_len);

/**
 * The value at percentile `p`, from zero to one hundred, into `out`. The
 * answer is a bucket boundary, since that is what the counts record.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_histogram_percentile(subetha_handle handle, double p, uint64_t *out);

/**
 * Zero every bucket. Peers sharing the file see the same empty histogram.
 */
int32_t subetha_histogram_reset(subetha_handle handle);

/**
 * Push the histogram's dirty pages to disk, returning when they are
 * durable.
 */
int32_t subetha_histogram_flush(subetha_handle handle);

/**
 * Start pushing the histogram's dirty pages to disk and return at once.
 */
int32_t subetha_histogram_flush_async(subetha_handle handle);

/**
 * A snapshot of the histogram into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_histogram_read_stats(subetha_handle handle, struct subetha_histogram_stats *out);

/**
 * Obtain the limiter at `path` holding `capacity` tokens and refilling
 * at `refill_rate_per_sec`: a full bucket is initialized when the file
 * does not exist, an existing one is attached with its live token count
 * in place. A limiter built with another capacity or rate is a
 * `SUBETHA_E_LAYOUT_MISMATCH`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_rate_limiter_create(const char *path,
                                    uint32_t capacity,
                                    uint32_t refill_rate_per_sec,
                                    uint32_t mode,
                                    subetha_handle *out);

/**
 * Attach to the limiter another process created at `path`; the file must
 * exist. `SUBETHA_E_IO` names an absent one.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_rate_limiter_open(const char *path,
                                  uint32_t capacity,
                                  uint32_t refill_rate_per_sec,
                                  uint32_t mode,
                                  subetha_handle *out);

/**
 * Take `n` tokens if they are there, and refuse with
 * `SUBETHA_E_WOULD_BLOCK` if they are not. A request above the capacity
 * is refused the same way, since no amount of waiting would meet it.
 */
int32_t subetha_rate_limiter_try_acquire(subetha_handle handle, uint32_t n);

/**
 * Take `n` tokens, waiting up to `timeout_ms` for the bucket to refill
 * enough. `SUBETHA_E_TIMEOUT` when the deadline passes first, and
 * `SUBETHA_E_WOULD_BLOCK` at once for a request above the capacity.
 *
 * The wait spins on the calling thread in either mode; the limiter
 * starts no thread of its own.
 */
int32_t subetha_rate_limiter_acquire_wait(subetha_handle handle, uint32_t n, uint64_t timeout_ms);

/**
 * Tokens available right now, into `out`. A snapshot: another process
 * may take them before the caller acts on it.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_rate_limiter_available(subetha_handle handle, uint32_t *out);

/**
 * Refill the bucket to its capacity. Peers sharing the file see the same
 * full bucket.
 */
int32_t subetha_rate_limiter_reset(subetha_handle handle);

/**
 * Push the limiter's dirty pages to disk, returning when they are
 * durable.
 */
int32_t subetha_rate_limiter_flush(subetha_handle handle);

/**
 * Start pushing the limiter's dirty pages to disk and return at once.
 */
int32_t subetha_rate_limiter_flush_async(subetha_handle handle);

/**
 * A snapshot of the limiter into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_rate_limiter_read_stats(subetha_handle handle,
                                        struct subetha_rate_limiter_stats *out);

/**
 * Obtain the barrier at `path`, counting peers in the heartbeat table
 * `heartbeat` names: an empty one is initialized when the file does not
 * exist, an existing one is attached at the epoch it stands at. A
 * `grace_epochs` of zero takes `SUBETHA_BARRIER_GRACE_DEFAULT`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_epoch_barrier_create(const char *path,
                                     subetha_handle heartbeat,
                                     uint64_t grace_epochs,
                                     uint32_t mode,
                                     subetha_handle *out);

/**
 * Attach to the barrier another process created at `path`; the file must
 * exist.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_epoch_barrier_open(const char *path,
                                   subetha_handle heartbeat,
                                   uint64_t grace_epochs,
                                   uint32_t mode,
                                   subetha_handle *out);

/**
 * Wait at `epoch` until every live peer has reached it. Blocks the
 * calling thread. `SUBETHA_E_BARRIER_EPOCH_PASSED` when the barrier is
 * already past `epoch`, and `SUBETHA_E_BARRIER_NO_LIVE_PEERS` when the
 * heartbeat table shows nobody to wait for.
 */
int32_t subetha_epoch_barrier_wait(subetha_handle handle, uint32_t epoch);

/**
 * `subetha_epoch_barrier_wait`, released once `quorum` peers have
 * arrived rather than all of them, so one straggler cannot hold a round.
 */
int32_t subetha_epoch_barrier_wait_quorum(subetha_handle handle, uint32_t epoch, uint32_t quorum);

/**
 * `subetha_epoch_barrier_wait` with a deadline; `SUBETHA_E_TIMEOUT` when
 * `timeout_ms` elapses first. The arrival stands, so a later wait at the
 * same epoch does not count this caller twice.
 */
int32_t subetha_epoch_barrier_wait_timeout(subetha_handle handle,
                                           uint32_t epoch,
                                           uint64_t timeout_ms);

/**
 * `subetha_epoch_barrier_wait_quorum` with a deadline.
 */
int32_t subetha_epoch_barrier_wait_quorum_timeout(subetha_handle handle,
                                                  uint32_t epoch,
                                                  uint32_t quorum,
                                                  uint64_t timeout_ms);

/**
 * The epoch the barrier stands at, into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_epoch_barrier_epoch(subetha_handle handle, uint32_t *out);

/**
 * Peers the heartbeat table shows as live, into `out`: how many an
 * unqualified wait waits for.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_epoch_barrier_live_peers(subetha_handle handle, uint32_t *out);

/**
 * A snapshot of the barrier into `out`. Every count races an arrival, so
 * it describes a moment that has already passed.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_epoch_barrier_read_stats(subetha_handle handle,
                                         struct subetha_epoch_barrier_stats *out);

/**
 * Flush the barrier's state to its file.
 */
int32_t subetha_epoch_barrier_flush(subetha_handle handle);

/**
 * Remove the barrier's file. On Windows the file must not be mapped by
 * any handle.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_epoch_barrier_unlink(const char *path, struct subetha_unlink_report *out);

/**
 * Obtain the fence clock at `path` with room for `capacity`
 * participants: an empty one is initialized when the file does not
 * exist, an existing one is attached with its registered slots and its
 * published fence in place. A file built with another capacity is a
 * `SUBETHA_E_LAYOUT_MISMATCH`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_fence_clock_create(const char *path,
                                   uint32_t capacity,
                                   uint32_t mode,
                                   subetha_handle *out);

/**
 * Attach to the fence clock another process created at `path`; the file
 * must exist.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_fence_clock_open(const char *path,
                                 uint32_t capacity,
                                 uint32_t mode,
                                 subetha_handle *out);

/**
 * Truncate the file at `path` and initialize an empty clock there,
 * dropping every registration. On Windows the file must not be mapped by
 * any handle.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_fence_clock_reset(const char *path,
                                  uint32_t capacity,
                                  uint32_t mode,
                                  subetha_handle *out);

/**
 * Take a slot for `pid` and write its index into `out_slot`. The index
 * is a plain number, not a handle: nothing is allocated for it and
 * nothing has to be destroyed, so a participant that registers and
 * unregisters repeatedly costs only the calls.
 * `SUBETHA_E_FENCE_CLOCK_FULL` when every slot is taken.
 *
 * # Safety
 * `out_slot` is a valid pointer.
 */
int32_t subetha_fence_clock_register(subetha_handle handle, uint32_t pid, uint32_t *out_slot);

/**
 * Give slot `slot` back, so it stops holding the global fence down and
 * the next participant can take it. A caller reclaiming after a crash
 * reads `pid` from `subetha_fence_clock_slot` and unregisters the ones
 * whose process is gone.
 */
int32_t subetha_fence_clock_unregister(subetha_handle handle, uint32_t slot);

/**
 * Step slot `slot`'s clock forward and write the new value into `out`.
 * Called as the participant does work, so what it publishes is at least
 * as late as anything it has done. `SUBETHA_E_INVALID_ARGUMENT`, with the
 * slot left as it was, when its logical part is already `UINT64_MAX` and
 * the shared clock has not moved past its physical part: no reading
 * orders after it.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_fence_clock_tick(subetha_handle handle, uint32_t slot, struct subetha_hlc *out);

/**
 * Take `remote` into slot `slot`'s clock and write the result into
 * `out`: the later of the two, stepped, so an event that caused the
 * remote one compares below it. This is what a receiver calls with the
 * value that traveled beside a message. `SUBETHA_E_INVALID_ARGUMENT`,
 * with the slot left as it was, when the logical part the merge steps is
 * already `UINT64_MAX`, which a remote clock can carry.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_fence_clock_merge(subetha_handle handle,
                                  uint32_t slot,
                                  struct subetha_hlc remote,
                                  struct subetha_hlc *out);

/**
 * Slot `slot`'s clock as it stands, without stepping it.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_fence_clock_get_local(subetha_handle handle,
                                      uint32_t slot,
                                      struct subetha_hlc *out);

/**
 * The latest clock across registered slots, computed now and written
 * into `out`: every event any participant has recorded stands at or
 * below it, so it is the point by which all of their work is accounted
 * for. This walks the slots without publishing what it finds.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_fence_clock_compute_global_fence(subetha_handle handle, struct subetha_hlc *out);

/**
 * Compute the fence and publish it, so every other process reads it
 * without walking the slots, and write it into `out`. One participant
 * doing this on a schedule is the usual arrangement.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_fence_clock_publish_global_fence(subetha_handle handle, struct subetha_hlc *out);

/**
 * The fence as last published, into `out`. Cheap: it reads one value
 * rather than walking the slots, which is what publishing is for.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_fence_clock_read_global_fence(subetha_handle handle, struct subetha_hlc *out);

/**
 * What slot `slot` holds, into `out`, and whether it is registered at
 * all into `out_registered`. An unregistered slot leaves `out`
 * untouched.
 *
 * # Safety
 * `out` and `out_registered` are valid pointers.
 */
int32_t subetha_fence_clock_read_slot(subetha_handle handle,
                                      uint32_t slot,
                                      struct subetha_fence_clock_slot *out,
                                      bool *out_registered);

/**
 * A snapshot of the clock into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_fence_clock_read_stats(subetha_handle handle,
                                       struct subetha_fence_clock_stats *out);

/**
 * Write the clock's dirty pages to its file.
 */
int32_t subetha_fence_clock_flush(subetha_handle handle);

/**
 * Remove the clock's file at `path`. The contract is
 * `subetha_ring_unlink`'s.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `report` is null or a valid
 * pointer.
 */
int32_t subetha_fence_clock_unlink(const char *path, struct subetha_unlink_report *report);

/**
 * Obtain the lazy value at `path`, holding `value_bytes`: an unclaimed
 * one is initialized when the file does not exist, and an existing one
 * is attached in whatever state it stands.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_lazy_create(const char *path,
                            size_t value_bytes,
                            uint32_t mode,
                            subetha_handle *out);

/**
 * Attach to the lazy value another process created at `path`, whose
 * value must be `value_bytes` long; the file must exist.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_lazy_open(const char *path, size_t value_bytes, uint32_t mode, subetha_handle *out);

/**
 * Take the right to produce the value, stamping the claim with `pid`,
 * and write whether this caller won into `out_won`.
 *
 * One caller wins. Every other is told it did not, whether because
 * another claim stands or because the value is already published, and
 * reads the value with `subetha_lazy_try_get` once it is published. A
 * claim whose process is gone is taken over by this call.
 *
 * # Safety
 * `out_won` is a valid pointer.
 */
int32_t subetha_lazy_claim(subetha_handle handle, uint32_t pid, bool *out_won);

/**
 * Publish the value produced under the claim `pid` holds, and release
 * the claim. `SUBETHA_E_LAZY_NOT_CLAIMED` when that claim is not the one
 * standing, so a caller that never won cannot overwrite the winner's
 * value.
 *
 * # Safety
 * `value` addresses `len` readable bytes.
 */
int32_t subetha_lazy_publish(subetha_handle handle, uint32_t pid, const uint8_t *value, size_t len);

/**
 * The published value into `out`, or `SUBETHA_E_LAZY_NOT_CLAIMED` while
 * none is published. Never blocks and never claims.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_lazy_try_get(subetha_handle handle, uint8_t *out, size_t cap, size_t *out_len);

/**
 * A snapshot of the value into `out`. The state races every claim and
 * publish, so it describes a moment that has already passed.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_lazy_read_stats(subetha_handle handle, struct subetha_lazy_stats *out);

/**
 * Flush the value to its file.
 */
int32_t subetha_lazy_flush(subetha_handle handle);

/**
 * Remove the value's file. On Windows the file must not be mapped by any
 * handle.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_lazy_unlink(const char *path, struct subetha_unlink_report *out);

/**
 * Obtain the value at `path` and take a holder slot: a region of
 * `value_bytes` holding `value` is initialized when the file does not
 * exist, and an existing one is attached with its contents in place.
 *
 * `value` is written only by the call that creates the backing; an
 * attach leaves what is there alone, as a second `Arc::clone` leaves
 * what the first one points at. A null `value` creates the region
 * zeroed.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `value` is null or addresses
 * `value_bytes` readable bytes; `out` is a valid pointer.
 */
int32_t subetha_shared_arc_create(const char *path,
                                  const uint8_t *value,
                                  size_t value_bytes,
                                  uint32_t max_holders,
                                  uint32_t on_last,
                                  uint32_t mode,
                                  subetha_handle *out);

/**
 * Attach to the value another process created at `path`, whose region
 * must be `value_bytes` long, and take a holder slot. A backing built
 * for another length or another holder count is a
 * `SUBETHA_E_LAYOUT_MISMATCH`.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_shared_arc_open(const char *path,
                                size_t value_bytes,
                                uint32_t max_holders,
                                uint32_t on_last,
                                uint32_t mode,
                                subetha_handle *out);

/**
 * Copy `len` bytes from `offset` in the shared region into `out`, and
 * the count into `out_len`.
 *
 * # Safety
 * `out` points to `cap` writable bytes; `out_len` is a valid pointer.
 */
int32_t subetha_shared_arc_read(subetha_handle handle,
                                size_t offset,
                                size_t len,
                                uint8_t *out,
                                size_t cap,
                                size_t *out_len);

/**
 * Copy `len` bytes from `src` into the shared region at `offset`.
 *
 * Not atomic and not ordered against another holder's read; see this
 * module's note on synchronizing writes.
 *
 * # Safety
 * `src` addresses `len` readable bytes.
 */
int32_t subetha_shared_arc_write(subetha_handle handle,
                                 size_t offset,
                                 const uint8_t *src,
                                 size_t len);

/**
 * Processes holding this value, into `out`, this one included.
 *
 * A holder whose process has died still counts until something reaps it.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_shared_arc_strong_count(subetha_handle handle, uint64_t *out);

/**
 * Free every holder slot whose process is gone and report how many went
 * into `out`, which may be null.
 *
 * # Safety
 * `out` is null or a valid pointer.
 */
int32_t subetha_shared_arc_reap_dead_holders(subetha_handle handle, uint64_t *out);

/**
 * A snapshot of the value into `out`. The holder count races every
 * attach and release, so it describes a moment that has already passed.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_shared_arc_read_stats(subetha_handle handle, struct subetha_shared_arc_stats *out);

/**
 * Flush the shared region to its file.
 */
int32_t subetha_shared_arc_flush(subetha_handle handle);

/**
 * Remove the value's file. On Windows the file must not be mapped by any
 * handle.
 *
 * A value created with `SUBETHA_ARC_UNLINK` removes its own backing when
 * the last holder releases, so this reports nothing removed once that
 * has happened.
 *
 * # Safety
 * `path` is a NUL-terminated UTF-8 string; `out` is a valid pointer.
 */
int32_t subetha_shared_arc_unlink(const char *path, struct subetha_unlink_report *out);

/**
 * Mint a self-signed certificate for `sni` and copy it and its private
 * key out as DER bytes. `cert_len` and `key_len` receive the byte counts
 * the call produced, or the counts it would need when a buffer is too
 * small, in which case the answer is `SUBETHA_E_BUFFER_TOO_SMALL` and
 * nothing is copied.
 *
 * The server half needs both; a client half needs the certificate alone,
 * and trusts exactly that one. `sni` names the certificate rather than
 * the wire address, so a peer reached at any address presents it.
 *
 * # Safety
 * `sni` is a NUL-terminated UTF-8 string. `cert_out` points to
 * `cert_cap` writable bytes and `key_out` to `key_cap`; both lengths are
 * valid pointers.
 */
int32_t subetha_quic_self_signed_cert(const char *sni,
                                      uint8_t *cert_out,
                                      size_t cert_cap,
                                      size_t *cert_len,
                                      uint8_t *key_out,
                                      size_t key_cap,
                                      size_t *key_len);

/**
 * Make the client half: it pulls from the ring `ring` names and ships to
 * `server_addr`, presenting `sni` and trusting the certificate in
 * `cert`. `bind_addr` is the local address to send from; `0.0.0.0:0`
 * takes any port the system offers.
 *
 * # Safety
 * `server_addr`, `bind_addr` and `sni` are NUL-terminated UTF-8 strings;
 * `cert` points to `cert_len` readable bytes; `out` is a valid pointer.
 */
int32_t subetha_quic_bridge_client(subetha_handle ring,
                                   const char *server_addr,
                                   const char *bind_addr,
                                   const char *sni,
                                   const uint8_t *cert,
                                   size_t cert_len,
                                   uint32_t mode,
                                   subetha_handle *out);

/**
 * Make the server half: it binds `addr`, accepts one connection and
 * pushes what arrives into the ring `ring` names, presenting the
 * certificate in `cert` with the key in `key`. Port zero binds a port
 * the system chooses, which `subetha_quic_bridge_local_port` reports.
 *
 * # Safety
 * `addr` is a NUL-terminated UTF-8 string; `cert` points to `cert_len`
 * readable bytes and `key` to `key_len`; `out` is a valid pointer.
 */
int32_t subetha_quic_bridge_server(subetha_handle ring,
                                   const char *addr,
                                   const uint8_t *cert,
                                   size_t cert_len,
                                   const uint8_t *key,
                                   size_t key_len,
                                   uint32_t mode,
                                   subetha_handle *out);

/**
 * The port the server half listens on, into `out`. For a server bound to
 * port zero this is the port the system chose.
 *
 * # Safety
 * `out` is a valid pointer.
 */
