int32_t subetha_reservoir_flush(subetha_handle handle);

/**
 * Start pushing the sampler's dirty pages to disk and return at once.
 */
int32_t subetha_reservoir_flush_async(subetha_handle handle);

/**
 * A snapshot of the sampler into `out`.
 *
 * # Safety
 * `out` is a valid pointer.
 */
int32_t subetha_reservoir_read_stats(subetha_handle handle, struct subetha_reservoir_stats *out);

/**
 * Create a ring in anonymous memory, reachable from this process only.
 * `capacity` is slots per backing and must be a power of two of at least 2.
 *
 * # Safety
 * `options` and `out` are valid pointers.
 */
